NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Deuteronomy'

CHAPTERS = {
    1: {
        1: 'To so besede, ki jih je Mojzes govoril vsemu Izraelu na tej strani Jordana, v divjini, na ravnini nasproti Rdečemu morju, med Paránom, Tofelom, Labánom, Hacerótom in Di Zahábom.',
        2: '(Tam je enajstdnevno potovanje od Horeba, po poti gorovja Seír do Kadeš Barnée.)',
        3: 'V štiridesetem letu, v enajstem mesecu, na prvi dan meseca, se je pripetilo, da je Mojzes spregovoril Izraelovim otrokom glede vsega, kar mu je Gospod dal njim v zapoved,',
        4: 'potem, ko je umoril amoréjskega kralja Sihóna, ki je prebival v Hešbónu in bašánskega kralja Oga, ki je prebival pri Aštarótu v Edréiju,',
        5: 'na tej strani Jordana, v moábski deželi, je Mojzes začel oznanjati to postavo, rekoč:',
        6: '» Gospod, naš Bog, nam je spregovoril na Horebu, rekoč: ›Dovolj dolgo ste prebivali na tej gori.',
        7: 'Obrnite se in pojdite na potovanje in pojdite h gori Amoréjcev in k vsem krajem blizu nje, na ravnini, na hribih, v dolini, na jugu in ob morski obali, k deželi Kánaancev in k Libanonu, k veliki reki, reki Evfrat.',
        8: 'Glejte, pred vas sem postavil deželo. Vstopite in vzemite v last deželo, ki jo je Gospod prisegel vašim očetom, Abrahamu, Izaku in Jakobu, da jo da njim in njihovemu semenu za njimi.‹',
        9: 'Ob tistem času sem vam govoril, rekoč: ›Nisem vas zmožen nositi sam.',
        10: 'Gospod, vaš Bog, vas je pomnožil in glejte, vas je ta dan kakor zvezd neba zaradi množice.',
        11: '(Gospod, Bog vaših očetov, naj vas naredi tisočkrat toliko, kot vas je in vas blagoslovi, kot vam je obljubil!)',
        12: 'Kako lahko jaz sam nosim vašo obremenitev, vaše breme in vaš prepir?',
        13: 'Vzemite si modre može, razumne in poznane med svojimi rodovi in jaz jih bom naredil voditelje nad vami.‹',
        14: 'Odgovorili ste mi in rekli: ›Stvar, ki si jo govoril, je za nas dobra, da [jo] storimo.‹',
        15: 'Tako sem vzel vodilne izmed vaših rodov, modre može in poznane in jih naredil poglavarje nad vami, tisočnike, stotnike, petdesetnike, desetnike in častnike med vašimi rodovi.',
        16: 'Ob tistem času sem zadolžil vaše sodnike, rekoč: ›Prisluhnite pravdam med vašimi brati in pravično sodite med vsakim možem, njegovim bratom in tujcem, ki je z njim.',
        17: 'Pri sodbi se ne boste ozirali na osebe; temveč boste prisluhnili tako majhnemu kakor velikemu. Ne boste se bali obličja človeka, kajti razsodba je Božja. Zadevo pa, ki je za vas pretežka, to prinesite k meni in ji bom prisluhnil.‹',
        18: 'Ob tistem času sem vam zapovedal vse stvari, ki naj bi jih storili.',
        19: 'Ko smo odpotovali od Horeba, smo odšli skozi vso to veliko in strašno divjino, ki ste jo videli po poti gore Amoréjcev, kakor nam je Gospod, naš Bog, zapovedal, in prišli smo do Kadeš Barnée.',
        20: 'Rekel sem vam: ›Prišli ste h gori Amoréjcev, ki nam jo daje Gospod, naš Bog.',
        21: 'Glej, Gospod, tvoj Bog je predte postavil deželo. Pojdi gor in si jo vzemi v last, kakor ti je rekel Gospod, Bog tvojih očetov. Ne boj se niti ne izgubi poguma.‹',
        22: 'Približali ste si mi, vsak izmed vas in rekli: ›Pred nami bomo poslali može in preiskali bodo deželo in nam ponovno prinesli besedo, po kateri poti moramo iti gor in v katera mesta bomo prišli.‹',
        23: 'Govor mi je ugajal, in izmed vas sem vzel dvanajst mož, enega iz rodu',
        24: 'in obrnili so se in odšli gor na goro in prišli v dolino Eškól in jo preiskali.',
        25: 'V svoje roke so vzeli od sadu dežele in to prinesli dol k nam in nam ponovno prinesli besedo ter rekli: › To je dobra dežela, ki nam jo daje Gospod, naš Bog.‹',
        26: 'Vendar niste hoteli iti gor, temveč [ste se] uprli zoper zapoved Gospoda, svojega Boga.',
        27: 'V svojih šotorih ste godrnjali in rekli: ›Zato, ker nas je Gospod sovražil, nas je privedel naprej, ven iz egiptovske dežele, da nas izroči v roke Amoréjcev, da nas uničijo.',
        28: 'Kam naj gremo gor? Naši bratje so našemu srcu vzeli pogum, rekoč: ›Ljudstvo je večje in višje, kakor smo mi. Mesta so velika in ograjena do neba, in poleg tega smo tam videli Anákove sinove.‹‹',
        29: 'Potem sem vam rekel: ›Ne bodite zaprepadeni niti se jih ne bojte.',
        30: 'Gospod, vaš Bog, ki gre pred vami, se bo boril za vas, glede na vse, kar je pred vašimi očmi za vas storil v Egiptu',
        31: 'in v divjini, kjer si videl, kako te je nosil Gospod, tvoj Bog, kakor mož nosi svojega sina, na vsej poti, kamor ste odšli, dokler niste prišli na ta kraj.‹',
        32: 'Vendar v tej stvari niste verovali Gospodu, svojemu Bogu,',
        33: 'ki je pred vami odšel na pot, da vam poišče prostor, da na njem postavite svoje šotore, v ognju ponoči, da vam pokaže po kateri pot naj bi šli, in v oblaku podnevi.',
        34: 'Gospod je slišal glas vaših besed in bil ogorčen ter prisegel, rekoč:',
        35: '›Zagotovo ne bo nobeden izmed teh mož tega zlega rodu videl te dobre dežele, za katero sem prisegel, da jo dam vašim očetom,',
        36: 'razen Jefunéjevega sina Kaléba; on jo bo videl in njemu bom dal deželo, po kateri je stopal in njegovim otrokom, ker je v celoti sledil Gospodu.‹',
        37: 'Prav tako je bil Gospod zaradi vas jezen name, rekoč: ›Ti tudi ne boš vstopil vanjo.',
        38: 'Toda Nunov sin Józue, ki stoji pred teboj, on bo vstopil tja. Ohrabri ga, kajti Izraelu bo povzročil, da jo podeduje.',
        39: 'Poleg tega bodo vaši malčki, za katere ste rekli, da bi morali biti plen in vaši otroci, ki na ta dan niso imeli spoznanja med dobrim in zlom, oni bodo vstopili tja in njim jo bom dal in oni jo bodo vzeli v last.',
        40: 'Toda kar se tiče vas, se obrnite in pojdite na potovanje v divjino, po poti Rdečega morja.‹',
        41: 'Potem ste mi odgovorili in rekli: ›Grešili smo zoper Gospoda, šli bomo gor in se borili, glede na vse, kar nam je zapovedal Gospod, naš Bog.‹ In ko ste si opasali vsak mož svoje bojno orožje, ste bili pripravljeni, da greste gor na hrib.',
        42: 'Gospod mi je rekel: ›Reci jim: ›Ne pojdite gor niti se ne bojujte, kajti jaz nisem med vami, da ne bi bili udarjeni pred svojimi sovražniki.‹‹',
        43: 'Tako sem vam govoril, pa niste hoteli slišati, temveč [ste se] uprli zoper Gospodovo zapoved in prepotentno odšli na hrib.',
        44: 'Amoréjci, ki prebivajo na tej gori, so prišli ven zoper vas in vas preganjali, kakor počnejo čebele in vas uničili v Seírju, celó do Horme.',
        45: 'Vrnili ste se in jokali pred Gospodom, toda Gospod ni hotel prisluhniti vašemu glasu niti nagniti ušesa k vam.',
        46: 'Tako ste mnogo dni ostali v Kadešu, glede na dneve, ko ste ostajali tam.',
    },
    2: {
        1: 'Potem smo se obrnili in šli na svoje potovanje v divjino, ob poti Rdečega morja, kakor mi je Gospod govoril in mnogo dni smo obkrožali gorovje Seír.',
        2: 'In Gospod mi je spregovoril, rekoč:',
        3: '›Dovolj dolgo ste obkrožali to goro, obrnite se proti severu.',
        4: 'Zapovej ljudstvu, rekoč: ›Šli boste skozi pokrajino svojih bratov, Ezavovih otrok, ki prebivajo v Seírju in oni se vas bodo bali, zato dobro pazite nase.',
        5: 'Ne vmešavajte se vanje, kajti ne bom vam dal od njihove dežele, ne, niti za širino stopala ne, ker sem gorovje Seír izročil Ezavu za posest.',
        6: 'Od njih boste hrano kupovali za denar, da boste lahko jedli in od njih boste tudi vodo kupovali za denar, da boste lahko pili.',
        7: 'Kajti Gospod, tvoj Bog, te je blagoslovil pri vseh delih tvoje roke. Pozna tvojo hojo skozi to veliko divjino. Teh štirideset let je bil Gospod, tvoj Bog, s teboj; nikakršnega pomanjkanja nisi trpel.‹‹',
        8: 'Ko smo šli mimo svojih bratov, Ezavovih otrok, ki so prebivali v Seírju, skozi pot ravnine od Eláta in od Ecjón Geberja, smo se obrnili in prešli po poti moábske divjine.',
        9: 'Gospod mi je rekel: ›Moábcev ne spravi v tegobo niti se z njimi ne spoprimi v boju, kajti njihove dežele ti ne bom dal v last, ker sem Ar dal Lotovim otrokom za posest.‹',
        10: 'Emejci so v njej prebivali v preteklih časih, veliko, številno in visoko ljudstvo, kakor Anákovci,',
        11: 'ki so bili tudi prišteti med velikane, kakor Anákovci, toda Moábci so jih imenovali Emejci.',
        12: 'Tudi Horéjci so poprej prebivali v Seírju, toda Ezavovi otroci so jih pregnali, ko so jih uničili pred seboj in prebivali namesto njih, kakor je Izrael storil v deželi njihove posesti, ki jim jo je dal Gospod.',
        13: '›Sedaj se vzdignite,‹ sem rekel ›in se odpravite čez potok Zered.‹ In šli smo preko potoka Zered.',
        14: 'Časa, v katerem smo prišli iz Kadeš Barnée, dokler nismo prešli preko potoka Zered, je bilo osemintrideset let, dokler ni pomrl ves rod bojevnikov izmed vojske, kakor jim je prisegel Gospod.',
        15: 'Kajti zares je bila Gospodova roka zoper njih, da jih uniči izmed vojske, dokler niso bili použiti.',
        16: 'Tako se je pripetilo, ko so bili vsi bojevniki izmed ljudstva použiti in mrtvi,',
        17: 'da mi je Gospod spregovoril, rekoč:',
        18: '›Danes boš prešel skozi Ar, moábsko pokrajino',
        19: 'in ko prideš blizu, nasproti Amónovih otrok, jih ne spravi v tegobo niti se ne vmešavaj vanje, kajti od dežele Amónovih otrok ti ne bom dal nobene posesti, ker sem jo dal Lotovim otrokom za posest.‹',
        20: '(Tudi ta je bila šteta [za] deželo velikanov. Tam so v starih časih prebivali velikani. Amónci so jih imenovali Zamzuméjce,',
        21: 'veliko, številno in visoko ljudstvo, kakor Anákovci. Toda Gospod jih je uničil pred njimi in oni so jih nasledili in prebivali namesto njih,',
        22: 'kakor je storil Ezavovim otrokom, ki so prebivali v Seírju, ko je pred njimi uničil Horéjce. Le-ti so jih nasledili in celo do tega dne prebivali namesto njih.',
        23: '§ Avéjce, ki so prebivali v Haserimu, celó do Gaze, so Kaftorejci, ki so izšli iz Kaftorja, uničili in prebivali namesto njih.)',
        24: '›Dvignite se, pojdite na potovanje in prečkajte reko Arnón. Glej, v tvojo roko sem izročil Amoréjca Sihóna, kralja v Hešbónu in njegovo deželo. Začnite jo jemati v last in se z njim spoprimite v bitki.',
        25: 'Danes bom začel pred teboj spuščati grozo in strah nad narode, ki so pod celotnim nebom, ki bodo slišali poročilo o tebi in bodo trepetali in bodo zaradi tebe v tesnobi.‹',
        26: 'In odposlal sem poslance iz divjine Kedemót k Sihónu, kralju v Hešbónu, z besedami miru, rekoč:',
        27: '›Naj grem skozi tvojo deželo. Šel bom vzdolž visoke poti, ne bom se obrnil niti k desni roki niti k levi.',
        28: 'Hrano mi boš prodajal za denar, da bom lahko jedel in vodo mi [boš] dajal za denar, da bom lahko pil, samo na svojih stopalih bom šel skozi',
        29: '(kakor so mi storili Ezavovi otroci, ki prebivajo v Seírju in Moábci, ki prebivajo v Aru), dokler ne bom šel čez Jordan v deželo, ki nam jo daje Gospod, naš Bog.‹',
        30: 'Toda Sihón, kralj v Hešbónu, nam ni dovolil iti mimo njega, kajti Gospod, tvoj Bog, je zakrknil njegovega duha in njegovo srce naredil trdovratno, da bi ga lahko izročil v tvojo roko, kakor se kaže ta dan.',
        31: 'Gospod mi je rekel: ›Glej, pred teboj sem ti začel dajati Sihóna in njegovo deželo. Začni jo jemati v last, da boš lahko podedoval njegovo deželo.‹',
        32: 'Potem je zoper nas prišel ven Sihón, on in njegovo ljudstvo, da se borijo pri Jahacu.',
        33: 'Gospod, naš Bog, ga je pred nami izročil in udarili smo njega, njegove sinove in vse njegovo ljudstvo.',
        34: 'Ob tistem času smo zavzeli vsa njegova mesta in popolnoma uničili moške, ženske in malčke iz vsakega mesta. Nobenega nismo pustili ostati.',
        35: 'Samo živino smo si vzeli za plen in ukradeno blago mest, ki smo jih zavzeli.',
        36: 'Od Aroêrja, ki je pri bregu reke Arnón in od mesta, ki je pri reki, celo do Gileáda, tam ni bilo niti enega mesta premočnega za nas. Gospod, naš Bog, jih je vsa izročil nam.',
        37: 'Samo v deželo Amónovih otrok nisi prišel niti v noben kraj reke Jabók niti v gorska mesta niti v katerakoli, ki nam jih je Gospod, naš Bog, prepovedal.',
    },
    3: {
        1: 'Potem smo se obrnili in odšli gor po poti do Bašána in bašánski kralj Og je prišel zoper nas, on in vse njegovo ljudstvo, da se bojuje pri Edréi.',
        2: 'Gospod mi je rekel: ›Ne boj se ga, kajti jaz bom izročil njega, vse njegovo ljudstvo in njegovo deželo, v tvojo roko in ti mu boš storil, kakor si storil Sihónu, kralju Amoréjcev, ki je prebival pri Hešbónu.‹',
        3: 'Tako je Gospod, naš Bog, v naše roke izročil tudi bašánskega kralja Oga in vse njegovo ljudstvo in udarjali smo ga, dokler mu nihče ni preostal.',
        4: 'Ob tistem času smo zavzeli vsa njegova mesta. Tam ni bilo mesta, ki ga ne bi vzeli od njih, šestdeset mest, celotno področje Argoba, Ogovo kraljestvo v Bašánu.',
        5: 'Vsa ta mesta so bila ograjena z visokimi zidovi, velikimi vrati in zapahi, poleg zelo veliko neobzidanih krajev.',
        6: 'Popolnoma smo jih uničili, kakor smo storili hešbónskemu kralju Sihónu. Popolnoma smo uničili moške, ženske in otroke vsakega mesta.',
        7: 'Toda vso živino in ukradeno blago mest smo si vzeli za plen.',
        8: 'Ob tistem času smo iz roke dveh kraljev Amoréjcev vzeli deželo, ki je bila na tej strani Jordana, od reke Arnón do gore Hermon',
        9: '(Hermon, katero Sidónci imenujejo Sirjón, Amoréjci pa jo imenujejo Senír))',
        10: 'vsa mesta ravnine, ves Gileád in ves Bašán, do Salhe in Edréi, mesta Ogovega kraljestva v Bašánu.',
        11: 'Kajti samo bašánski kralj Og je preostal od preostanka velikanov. Glej, ogrodje njegove postelje je bilo posteljno ogrodje iz železa. Mar ni ta v Rabi Amónovih sinov? Devet komolcev je bila njena dolžina in štiri komolce njena širina, po moškem komolcu.',
        12: 'To deželo, ki smo jo ob tistem času vzeli v last od Aroêrja, ki je ob reki Arnón in polovico gore Gileád in njena mesta, sem dal Rubenovcem in Gádovcem.',
        13: 'Preostanek Gileáda in ves Bašán, ki je Ogovo kraljestvo, sem dal polovici Manásejevega rodu in vse področje Argoba, z vsem Bašánom, ki je bil imenovan dežela velikanov.',
        14: 'Jaír, sin Manáseja, je zavzel vso Argobovo deželo do pokrajin Gešurja in Maahčánov, in imenoval jih je po svojem imenu Bašán Havot Jaír do današnjega dne.',
        15: 'In jaz sem Gileád izročil Mahírju.',
        16: 'Rubenovcem in Gádovcem sem dal od Gileáda celo do reke Arnón, polovico doline in mejo celo do reke Jabók, ki je meja Amónovih otrok;',
        17: 'tudi ravnino in Jordan in njegovo pokrajino od Kinéreta, celó do morja ravnine, celo slanega morja, vzhodno pod Ašdód-Pisgo.',
        18: 'Ob tem času sem vam zapovedal, rekoč: › Gospod, vaš Bog, vam je to deželo dal v last. Čeznjo boste prešli oboroženi pred svojimi brati, Izraelovimi otroki, vsemi, ki so primerni za vojno.',
        19: 'Toda vaše žene, vaši malčki in vaša živina (kajti vem, da imate mnogo živine), bodo ostali v vaših mestih, ki sem vam jih dal,',
        20: 'dokler Gospod ne da počitka vašim bratom, prav tako kakor vam in dokler tudi oni ne vzamejo v last dežele, ki jim jo je Gospod, vaš Bog, dal onkraj Jordana. In potem se boste vrnili, vsak mož k svoji posesti, ki sem vam jo dal.‹',
        21: 'Ob tistem času sem Józuetu zapovedal, rekoč: ›Tvoje oči so videle vse, kar je Gospod, tvoj Bog, storil tema dvema kraljema. Tako bo Gospod storil vsem kraljestvom, ki jih vzameš v last.',
        22: 'Ne boste se jih bali, kajti za vas se bo boril Gospod, vaš Bog.‹',
        23: 'Ob tistem času sem prosil Gospoda, rekoč:',
        24: '›Oh Gospod Bog, svojim služabnikom si začel kazati svojo veličino in svojo mogočno roko, kajti kakšen Bog je tam v nebesih ali na zemlji, ki lahko stori glede na tvoja dela in glede na tvojo moč?',
        25: 'Prosim te, naj grem preko in vidim dobro deželo, ki je onkraj Jordana, to dobro goro in Libanon.‹',
        26: 'Toda Gospod je bil zaradi vas ogorčen name in me ni hotel uslišati. Gospod mi je rekel: ›Naj ti to zadošča. Ne govori mi več o tej zadevi.',
        27: 'Povzpni se na vrh Pisge in povzdigni svoje oči proti proti zahodu, proti severu, proti jugu in proti vzhodu in glej to s svojimi očmi, kajti ne boš šel preko tega Jordana.',
        28: 'Toda zadolži Józueta, ga ohrabri in okrépi, kajti on bo pred tem ljudstvom šel preko in povzročil jim bo, da podedujejo deželo, ki jo boš videl.‹',
        29: 'Tako smo ostali v dolini nasproti Bet Peórja.',
    },
    4: {
        1: 'Zdaj torej prisluhni, oh Izrael, zakonom in sodbam, ki vas jih učim, da jih izpolnjujete, da boste lahko živeli, vstopili in vzeli v last deželo, ki vam jo daje Gospod, Bog vaših očetov.',
        2: 'Ne boste dodajali besedi, ki sem vam jo zapovedal niti ne boste zmanjševali česa od nje, da bi lahko ohranjali zapovedi Gospoda, svojega Boga, ki sem vam jih zapovedal.',
        3: 'Vaše oči so videle kaj je Gospod storil zaradi Báal Peórja. Zaradi vseh mož, ki so sledili Báal Peórju, jih je Gospod, tvoj Bog, uničil izmed vas.',
        4: 'Toda vi, ki ste se trdno držali Gospoda, svojega Boga, ste danes živi, vsakdo izmed vas.',
        5: 'Glejte, učil sem vas zakonov in sodb, celo kakor mi je Gospod, moj Bog, zapovedal, da naj bi storili v deželi, kamor greste, da jo vzamete v last.',
        6: 'Torej jih ohranjajte in izpolnjujte, kajti to je vaša modrost in vaše razumevanje v očeh narodov, ki bodo slišali vse te zakone in rekli: ›Zagotovo je ta véliki narod modro in razumevajoče ljudstvo.‹',
        7: 'Kajti kateri narod je tam tako velik, ki ima Boga tako blizu, kakor je Gospod, naš Bog, v vseh stvareh, za katere kličemo k njemu?',
        8: 'In kateri narod je tam tako velik, ki ima zakone in sodbe tako pravične, kot je vsa ta postava, ki jo danes postavljam pred vas?',
        9: 'Samo pazi nase in marljivo varuj svojo dušo, da ne pozabiš stvari, ki so jih videle tvoje oči in da vse dni tvojega življenja ne odidejo od tvojega srca, temveč poučuj svoje sinove in svojih sinov sinove,',
        10: 'posebej [o] dnevu, ko si stal pred Gospodom, svojim Bogom, na Horebu, ko mi je Gospod rekel: ›Zberi mi skupaj ljudstvo in pripravil jih bom slišati moje besede, da se me bodo lahko naučili bati vse dni, ki jih bodo živeli na zemlji in da bodo lahko učili svoje otroke.‹',
        11: 'In približali ste se ter stali pod goro in gora je gorela z ognjem do srede neba, s temo, oblaki in gosto temo.',
        12: 'Gospod vam je spregovoril iz srede ognja. Slišali ste glas besed, toda nobene podobnosti niste videli, samo glas ste slišali.',
        13: 'Naznanil vam je svojo zavezo, ki vam jo je zapovedal, da jo opravljate, torej deset zapovedi, in napisal jih je na dve kamniti plošči.',
        14: 'Gospod mi je ob tistem času zapovedal, da vas učim zakone in sodbe, da jih boste lahko izpolnjevali v deželi, kamor greste, da jo vzamete v last.',
        15: 'Zato torej dobro pazite nase, kajti nobene vrste podobnosti niste videli na dan, ko vam je Gospod govoril na Horebu iz srede ognja,',
        16: 'da se ne bi izpridili in si naredili rezane podobe, podobnost kakršnekoli postave, podobnost moškega ali ženske,',
        17: 'podobnost katerekoli živali, ki je na zemlji, podobnost katerekoli krilate perjadi, ki leti po zraku,',
        18: 'podobnost katerekoli stvari, ki se plazi po tleh, podobnost katerekoli ribe, ki je v vodah pod zemljo,',
        19: 'in da ne bi povzdignil svojih oči k nebu in ko zagledaš sonce, luno in zvezde, celó vso vojsko neba, da ne bi bil zapeljan, da jih obožuješ in jim služiš, ki jih je Gospod, tvoj Bog, razdelil vsem narodom pod celotnim nebom.',
        20: 'Toda Gospod vas je vzel in vas privedel naprej iz železne talilne peči, torej iz Egipta, da mu boste ljudstvo dediščine, kakor ste ta dan.',
        21: 'Nadalje je bil zaradi vas Gospod jezen nad menoj in prisegel, da naj ne bi šel preko Jordana in da naj ne bi vstopil v to dobro deželo, ki ti jo Gospod, tvoj Bog, daje v dediščino,',
        22: 'temveč moram umreti v tej deželi, ne smem iti čez Jordan. Toda vi boste šli čez in tisto dobro deželo vzeli v last.',
        23: 'Pazite nase, da ne bi pozabili zaveze Gospoda, svojega Boga, ki jo je sklenil z vami in si naredili rezane podobe ali podobnost katerekoli stvari, ki ti jo je Gospod, tvoj Bog, prepovedal.',
        24: 'Kajti Gospod, tvoj Bog, je požirajoč ogenj, celó ljubosumen Bog.',
        25: 'Ko boš zaplodil otroke in otrok otroke in boste dolgo ostali v deželi in se boste izpridili in naredili rezano podobo ali podobnost katerikoli stvari in boste počeli zlo v očeh Gospoda, svojega Boga, da ga dražite k jezi,',
        26: 'pokličem nebo in zemljo, da ta dan pričujeta zoper vas, da boste kmalu popolnoma izginili iz dežele, v katero ste šli prek Jordana, da jo vzamete v last. Ne boste podaljšali svojih dni na njej, temveč boste popolnoma uničeni.',
        27: 'Gospod vas bo razkropil med narode in malo vas bo ostalo po številu med pogani, kamor vas bo vodil Gospod.',
        28: 'Tam boste služili bogovom, delu človeških rok, lesu in kamnu, ki niti ne vidita niti ne slišita, ne jesta niti ne vonjata.',
        29: 'Toda če boš od tam iskal Gospoda, svojega Boga, ga boš našel, če ga iščeš z vsem svojim srcem in z vso svojo dušo.',
        30: 'Ko si v stiski in vse te stvari pridejo nadte, torej v zadnjih dneh, če se obrneš h Gospodu, svojemu Bogu in boš poslušen njegovemu glasu',
        31: '(kajti Gospod, tvoj Bog, je usmiljen Bog) te ne bo zapustil niti uničil niti pozabil zaveze tvojih očetov, ki jim jo je prisegel.',
        32: 'Kajti vprašaj sedaj o dneh, ki so minili, ki so bili pred teboj, od dneva, ko je Bog na zemlji ustvaril moža in vprašaj od ene strani neba do druge, ali je bila tam kakršna koli takšna stvar, kot je ta velika stvar, ali je bila slišati podobno?',
        33: 'Mar je kdajkoli ljudstvo slišalo glas Boga govoriti iz srede ognja, kakor si slišal ti, in je živelo?',
        34: 'Mar je Bog poskušal iti in si vzeti narod iz srede drugega naroda, s preizkušnjami, znamenji, čudeži, vojno, mogočno roko, z iztegnjenim laktom in z velikimi strahotami, glede na vse, kar je Gospod, vaš Bog, storil za vas v Egiptu, pred vašimi očmi?',
        35: 'Tebi je bilo pokazano, da bi lahko vedel, da Gospod, on je Bog. Tam ni nobenega drugega poleg njega.',
        36: 'Iz nebes ti je dal, da slišiš njegov glas, da bi te lahko poučil, in na zemlji ti je pokazal svoj velik ogenj in ti slišiš njegove besede iz srede ognja.',
        37: 'Ker je vzljubil tvoje očete, zato je izbral tvoje seme za njimi in te privedel ven v njegovem pogledu, s svojo mogočno močjo iz Egipta,',
        38: 'da izpred tebe napodi narode, večje in mogočnejše kakor si ti, da te privede noter, da ti da njihovo deželo v dediščino, kakor je to ta dan.',
        39: 'Vedi torej danes in preudari to v svojem srcu, da Gospod, on je Bog, v nebesih zgoraj in na zemlji spodaj. Tam ni nobenega drugega.',
        40: 'Ohranjal boš torej njegove zakone in njegove zapovedi, ki ti jih danes zapovedujem, da bo lahko šlo dobro s teboj in s tvojimi otroki za teboj in da lahko podaljšaš svoje dneve na zemlji, ki ti jo daje Gospod, tvoj Bog, na veke.«',
        41: 'Potem je Mojzes oddvojil tri mesta na tej strani Jordana proti sončnemu vzhodu,',
        42: 'da bi ubijalec, ki bi nenamerno ubil svojega bližnjega in ga v preteklih časih ni sovražil, lahko pobegnil tja in da bežeč v eno izmed teh mest lahko ostane živ.',
        43: 'Namreč Becer v divjini, na ravnini dežele Rubenovcev in Ramót v Gileádu od Gádovcev in Golán v Bašánu od Manásejcev.',
        44: 'To je postava, ki jo je Mojzes postavil pred Izraelove otroke.',
        45: 'To so pričevanja, zakoni in sodbe, ki jih je Mojzes govoril Izraelovim otrokom, po tem, ko so izšli iz Egipta,',
        46: 'na tej strani Jordana, v dolini nasproti Bet Peórja, v deželi amoréjskega kralja Sihóna, ki je prebival v Hešbónu, ki so ga Mojzes in Izraelovi otroci udarili, potem ko so izšli iz Egipta.',
        47: 'Vzeli so v last njegovo deželo in deželo bašánskega kralja Oga, dveh kraljev Amoréjcev, ki sta bila na tej strani Jordana, proti sončnemu vzhodu;',
        48: 'od Aroêrja, ki je ob bregu reke Arnón, celo do gore Sion, ki je Hermon',
        49: 'in vso ravnino na tej strani Jordana proti vzhodu, celo do morja ravnine, pod izviri Pisge.',
    },
    5: {
        1: 'Mojzes je sklical ves Izrael in jim rekel: »Poslušaj, oh Izrael, zakone in sodbe, ki jih ta dan govorim v vaša ušesa, da se jih lahko naučite in jih ohranjate in jih izvršujete.',
        2: 'Gospod, naš Bog, je z nami sklenil zavezo na Horebu.',
        3: 'Gospod te zaveze ni sklenil z našimi očeti, temveč z nami, torej nami, ki smo, vsi izmed nas, ta dan tukaj živi.',
        4: 'Gospod je s teboj govoril iz obličja v obličje, na gori, iz srede ognja',
        5: '(ob tistem času sem stal med Gospodom in vami, da bi vam pokazal Gospodovo besedo, kajti vi ste se zaradi ognja bali in niste šli gor na goro), rekoč:',
        6: '[1] ›Jaz sem Gospod, tvoj Bog, ki te je privedel iz egiptovske dežele, iz hiše sužnosti.',
        7: '[2] Pred menoj ne boš imel nobenih drugih bogov.',
        8: 'Sebi ne boš naredil nobene rezane podobe ali kakršnekoli podobnosti katerekoli stvari, ki je v nebesih zgoraj ali ki je na zemlji spodaj ali ki je v vodah pod zemljo.',
        9: 'Ne boš se jim priklanjal niti jim služil, kajti jaz, Gospod, tvoj Bog, sem ljubosumen Bog, ki obiskujem krivičnost očetov na otrocih do tretjega in četrtega rodu teh, ki me sovražijo',
        10: 'in izkazujem usmiljenje tisočim tistih, ki me ljubijo in varujejo moje zapovedi.',
        11: '[3] Ne boš v prazno vzel imena Gospoda, svojega Boga, kajti Gospod ne bo brez krivde držal tistega, ki v prazno jemlje njegovo ime.',
        12: '[4] Varuj šabatni dan, da ga posvečuješ, kakor ti je zapovedal Gospod, tvoj Bog.',
        13: 'Šest dni se boš trudil in opravljal vse svoje delo,',
        14: 'toda sedmi dan je šabat Gospodu, tvojemu Bogu. Na [ta dan] ne boš opravljal nobenega dela, ne ti, niti tvoj sin, niti tvoja hči, niti tvoj sluga, niti tvoja dekla, niti tvoj vol, niti tvoj osel, niti nobena izmed tvoje živine, niti tvoj tujec, ki je znotraj tvojih velikih vrat, da lahko tvoj sluga in tvoja dekla počivata kakor ti.',
        15: 'Spominjaj pa se, da si bil služabnik v egiptovski deželi in da te je Gospod, tvoj Bog, od tam privedel z mogočno roko in z iztegnjenim laktom. Zato ti je Gospod, tvoj Bog, zapovedal, da izvajaš šabatni dan.',
        16: '[5] Spoštuj svojega očeta in svojo mater, kakor ti je zapovedal Gospod, tvoj Bog, da bodo tvoji dnevi lahko podaljšani in da ti bo dobro šlo v deželi, ki ti jo daje Gospod, tvoj Bog.',
        17: '[6] Ne boš ubil.',
        18: '[7] Niti ne boš zagrešil zakonolomstva.',
        19: '[8] Niti ne boš kradel.',
        20: '[9] Niti ne boš pričal po krivem zoper svojega bližnjega.',
        21: '[10] Niti si ne boš želel žene svojega bližnjega, niti ne boš hlepel [po] hiši svojega bližnjega, [po] njegovem polju ali [po] njegovem slugi ali [po] njegovi dekli, [po] njegovem volu ali [po] njegovem oslu ali [po] katerikoli stvari, ki je [od] tvojega bližnjega.‹',
        22: 'Te besede je Gospod govoril vsemu zboru na gori, iz srede ognja, iz oblaka in iz goste teme, z močnim glasom. In ni več dodal. Napisal jih je na dve kamniti plošči in mi ju izročil.',
        23: 'Pripetilo se je, ko ste iz srede teme zaslišali glas (kajti gora je gorela z ognjem), da ste se mi približali, celó vsi poglavarji vaših rodov in vaše starešine',
        24: 'in ste rekli: ›Glej, Gospod, naš Bog, nam je pokazal svojo slavo in svojo veličino in iz srede ognja smo slišali njegov glas. Ta dan smo videli, da Bog govori z možem in ta živi.',
        25: 'Zdaj torej zakaj naj bi umrli? Kajti ta velik ogenj nas bo použil. Če še naprej slišimo glas Gospoda, našega Boga, potem bomo umrli.',
        26: 'Kajti kdo je tam od vsega mesa, ki je iz srede ognja slišal govoriti glas živega Boga, kakor smo mi in je živel?',
        27: 'Ti pojdi blizu in prisluhni vsemu, kar bo rekel Gospod, naš Bog in spregovori nam vse, kar ti bo govoril Gospod, naš Bog in mi bomo temu prisluhnili in to storili.‹',
        28: 'Gospod je slišal glas vaših besed, ko ste mi govorili in Gospod mi je rekel: ›Slišal sem glas besed tega ljudstva, ki so ti jih govorili. Dobro so povedali vse, kar so govorili.',
        29: 'Oh, da bi bilo takšno srce v njih, da bi se me bali in se vedno držali vseh mojih zapovedi, da bi bilo lahko dobro z njimi in z njihovimi otroki na veke!',
        30: 'Pojdi, reci jim: ›Ponovno se vrnite v svoje šotore.‹',
        31: 'Toda kar se tebe tiče, ti ostani tukaj, poleg mene in govoril ti bom vse zapovedi, zakone in sodbe, ki jih boš učil, da jih bodo lahko izpolnjevali v deželi, ki sem jim jo dal, da jo vzamejo v last.‹',
        32: 'Obeleževali boste torej, da delate, kakor vam je zapovedal Gospod, vaš Bog. Ne boste se odvrnili vstran, ne k desni roki ne k levi.',
        33: 'Hodili boste po vseh poteh, ki vam jih je zapovedal Gospod, vaš Bog, da boste lahko živeli in da bo lahko dobro z vami in da boste lahko podaljšali svoje dni v deželi, ki jo boste vzeli v last.',
    },
    6: {
        1: 'Torej to so zapovedi, zakoni in sodbe, ki jih je Gospod, vaš Bog, zapovedal, da vas učim, da jih boste lahko izpolnjevali v deželi, kamor greste, da jo vzamete v last,',
        2: 'da se boš lahko bal Gospoda, svojega Boga, da boš ohranjal vse njegove zakone in njegove zapovedi, ki sem ti jih zapovedal: ti, tvoj sin in sin tvojega sina, vse dni tvojega življenja in da bodo tvoji dnevi lahko podaljšani.',
        3: 'Poslušaj torej, oh Izrael in obeležuj, da to storiš, da bo lahko dobro s teboj in da boš lahko mogočno povečan, kakor ti je obljubil Gospod, Bog tvojih očetov, v deželi, kjer tečeta mleko in med.',
        4: 'Poslušaj, oh Izrael: › Gospod, naš Bog, je edini Gospod',
        5: 'in ljubil boš Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo in z vso svojo močjo.‹',
        6: 'In te besede, ki sem ti jih danes zapovedal, bodo v tvojem srcu.',
        7: 'In ti jih boš marljivo učil svoje otroke in boš govoril o njih, ko sediš v svoji hiši, ko hodiš po poti, ko se uležeš in ko vstajaš.',
        8: 'Privezal si jih boš za znamenje na roko in te bodo kot načelek med tvojimi očmi.',
        9: 'Napisal jih boš na podboje svoje hiše in na svoja velika vrata.',
        10: 'In zgodilo se bo, ko te bo Gospod, tvoj Bog, privedel v deželo, ki jo je prisegel tvojim očetom, Abrahamu, Izaku in Jakobu, da ti da velika in čedna mesta, ki jih nisi zgradil',
        11: 'in hiše, polne vseh dobrih stvari, ki jih nisi napolnil in izkopane vodnjake, ki jih nisi izkopal, vinograde in oljke, ki jih nisi zasadil; ko jih boš jedel in boš sit,',
        12: 'potem se pazi, da ne pozabiš Gospoda, ki te je privedel iz egiptovske dežele, iz hiše sužnosti.',
        13: 'Bal se boš Gospoda, svojega Boga in mu služil in prisegal pri njegovem imenu.',
        14: 'Ne boste šli za drugimi bogovi, bogovi ljudstev, ki so naokoli vas',
        15: '(kajti Gospod, tvoj Bog, je med vami ljubosumen Bog), da ne bi bila zoper tebe vžgana jeza Gospoda, tvojega Boga in te uniči iz obličja zemlje.',
        16: 'Ne boste skušali Gospoda, svojega Boga, kakor ste ga skušali v Masi.',
        17: 'Marljivo boste varovali zapovedi Gospoda, svojega Boga, njegova pričevanja in njegove zakone, ki ti jih je zapovedal.',
        18: 'Storil boš to, kar je prav in dobro v Gospodovih očeh, da bo lahko dobro s teboj in da lahko vstopiš in vzameš v last dobro deželo, ki jo je Gospod prisegel tvojim očetom,',
        19: 'da pred teboj prežene vse tvoje sovražnike, kakor je govoril Gospod.',
        20: 'In ko te tvoj sin sprašuje v času, ki pride, rekoč: ›Kaj pomenijo pričevanja, zakoni in sodbe, ki vam jih je zapovedal Gospod, naš Bog?‹',
        21: 'Potem boš svojemu sinu rekel: ›V Egiptu smo bili faraonovi sužnji in Gospod nas je z mogočno roko privedel iz Egipta.',
        22: 'Gospod je pred našimi očmi nad Egiptom, nad faraonom in nad vso njegovo hišo pokazal znamenja in čudeže, velika in boleča',
        23: 'in nas odvedel od tam, da bi nas lahko privedel noter, da nam da deželo, ki jo je prisegel našim očetom.',
        24: 'Gospod nam je zapovedal, da izvršujemo vse te zakone, da se vedno bojimo Gospoda, svojega Boga, za naše dobro, da nas lahko ohrani žive, kakor je to na ta dan.',
        25: 'In to bo naša pravičnost, če obeležujemo vse te zapovedi pred Gospodom, svojim Bogom, kakor nam je zapovedal.‹',
    },
    7: {
        1: 'Ko te bo Gospod, tvoj Bog, privedel v deželo, kamor greš, da jo vzameš v last in je pred teboj pregnal mnoge narode: Hetejce, Girgašéjce, Amoréjce, Kánaance, Perizéjce, Hivéjce in Jebusejce, sedem narodov, večje in mogočnejše kakor ti,',
        2: 'in ko jih bo Gospod, tvoj Bog, izročil pred teboj, jih boš udaril in popolnoma uničil. Nobene zaveze ne boš sklenil z njimi niti jim ne izkaži usmiljenja,',
        3: 'niti z njimi ne boš sklepal porok. Svoje hčere ne boš dal njegovemu sinu niti njegove hčere ne boš vzel k svojemu sinu.',
        4: 'Kajti tvojega sina bodo odvrnile od sledenja meni, da bi lahko služile drugim bogovom. Tako bo zoper tebe vžgana Gospodova jeza in te nenadoma uniči.',
        5: 'Temveč boste tako postopali z njimi: uničili boste njihove oltarje in razbili njihove podobe in posekali njihove ašere in njihove rezane podobe sežgali z ognjem.',
        6: 'Kajti ti si sveto ljudstvo Gospodu, svojemu Bogu. Gospod, tvoj Bog, te je izbral, da mu boš posebno ljudstvo, nad vsemi ljudstvi, ki so na obličju zemlje.',
        7: 'Gospod svoje ljubezni ni naravnal na vas niti vas ni izbral, ker ste bili številnejši kot katerokoli ljudstvo, kajti bilo vas je najmanj izmed vseh ljudstev,',
        8: 'temveč, ker vas je Gospod ljubil in ker je želel držati prisego, ki jo je prisegel vašim očetom, vas je Gospod izpeljal z mogočno roko in vas odkupil iz hiše sužnosti, iz roke faraona, egiptovskega kralja.',
        9: 'Vedi torej, da Gospod, tvoj Bog, on je Bog, zvesti Bog, ki ohranja zavezo in usmiljenje s tistimi, ki ga ljubijo in ohranjajo njegove zapovedi tisočim rodovom.',
        10: 'Tistim pa, ki ga sovražijo, poplača k njihovemu obrazu, da jih uniči. Ne bo počasen do tistega, ki ga sovraži; poplačal mu bo v obraz.',
        11: 'Torej boš varoval zapovedi, zakone in sodbe, ki sem ti jih ta dan zapovedal, da jih izvršuješ.',
        12: 'Kjerkoli se bo to pripetilo, če prisluhnete tem sodbam in jih varujete in jih izpolnjujete, da ti bo Gospod, tvoj Bog, varoval zavezo in usmiljenje, ki ga je prisegel tvojim očetom.',
        13: 'Ljubil te bo, te blagoslavljal in te namnožil. Blagoslavljal bo tudi sad tvoje maternice in sad tvoje dežele, tvoje žito, tvoje vino in tvoje olje, narast tvojega goveda in trope tvojih ovc, v deželi, ki jo je prisegel tvojim očetom, da ti jo da.',
        14: 'Blagoslovljen boš nad vsemi ljudstvi. Med vami ne bo jalovega moškega ali ženske ali med vašo živino.',
        15: 'Gospod bo od tebe odvrnil vso bolezen in nobene izmed teh zlih egiptovskih bolezni, ki jih poznaš, ne bo položil nadte, temveč jih bo položil na vse tiste, ki te sovražijo.',
        16: 'Použil boš vsa ljudstva, ki ti jih bo izročil Gospod, tvoj Bog. Tvoje oko nad njimi ne bo imelo nobenega usmiljenja. Niti ne boš služil njihovim bogovom, kajti to ti bo zanka.',
        17: 'Če boš v svojem srcu rekel: ›Ti narodi so številnejši kakor jaz; kako jih lahko razlastim?‹',
        18: 'Ne boš se jih bal, temveč se boš dobro spomnil, kaj je Gospod, tvoj Bog, storil faraonu in vsemu Egiptu:',
        19: 'velike preizkušnje, ki so jih videle tvoje oči, znamenja, čudeže, mogočno roko in iztegnjen laket, s čimer te je izpeljal Gospod, tvoj Bog. Tako bo Gospod, tvoj Bog, storil vsem ljudstvom, ki se jih bojiš.',
        20: 'Poleg tega bo Gospod, tvoj Bog, mednje poslal sršene, dokler ne bodo tisti, ki so preostali in se skrivajo pred teboj, uničeni.',
        21: 'Pred njimi ne boš zgrožen, kajti Gospod, tvoj Bog, je med vami mogočen in strašen Bog.',
        22: 'In Gospod, tvoj Bog, bo te narode po malo in malo odstranil pred teboj. Ne boš jih mogel naenkrat použiti, da ne bi poljske zveri narasle nad teboj.',
        23: '§ Toda Gospod, tvoj Bog, jih bo izročil tebi in uničeval jih boš z mogočnim uničenjem, dokler ne bodo uničeni.',
        24: 'Njihove kralje bo izročil v tvojo roko in njihovo ime boš uničil izpod neba. Noben človek ne bo zmožen obstati pred teboj, dokler jih ne uničiš.',
        25: 'Rezane podobe njihovih bogov boste sežgali z ognjem. Ne boš hlepel po srebru ali zlatu, ki je na njih niti si ga ne vzemi k sebi, da ne bi bil v tem ujet, kajti to je ogabnost Gospodu, tvojemu Bogu.',
        26: 'Niti v svojo hišo ne prinašaj gnusobe, da ne bi bil preklet, kakor je ona, temveč naj se ti skrajno gnusi in skrajno jo zaničuj, kajti to je prekleta stvar.',
    },
    8: {
        1: 'Vse zapovedi, ki sem ti jih ta dan zapovedal, boste obeleževali, da jih izvršujete, da boste lahko živeli, se množili in vstopili in vzeli v last deželo, ki jo je Gospod prisegel vašim očetom.',
        2: 'Spomnil se boš celotne poti, po kateri te je Gospod, tvoj Bog, teh štirideset let vodil po divjini, da te poniža in te preizkusi, da spozna kaj je bilo v tvojem srcu, bodisi se boš držal njegovih zapovedi ali ne.',
        3: 'Ponižal te je in ti dopustil, da si bil lačen in te hranil z mano, ki je nisi poznal niti je niso poznali tvoji očetje, da bi ti on lahko dal spoznati, da človek ne živi samo od kruha, temveč človek živi od vsake besede, ki izhaja iz Gospodovih ust.',
        4: 'Teh štirideset let se tvoja obleka na tebi ni postarala niti tvoje stopalo ni oteklo.',
        5: 'V svojem srcu boš tudi preudaril, da kakor mož kara svojega sina, tako Gospod, tvoj Bog, kara tebe.',
        6: 'Zatorej boš varoval zapovedi Gospoda, svojega Boga, da hodiš po njegovih poteh in da se ga bojiš.',
        7: 'Kajti Gospod, tvoj Bog, te vodi v dobro deželo, deželo vodnih potokov, studencev in globin, ki privrejo iz dolin in hribov;',
        8: 'deželo pšenice, ječmena, trt, figovih dreves in granatnih jabolk; deželo olivnega olja in medu;',
        9: 'deželo, v kateri boš jedel kruh brez pomanjkanja, v njej ti ne bo primanjkovalo nobene stvari; deželo, katere kamni so železo in iz katerih hribov lahko koplješ bron.',
        10: 'Ko se naješ in si sit, potem boš blagoslovil Gospoda, svojega Boga, zaradi dobre dežele, ki ti jo je dal.',
        11: 'Pazi se, da ne pozabiš Gospoda, svojega boga, da se ne bi držal njegovih zapovedi, njegovih sodb in njegovih zakonov, ki sem ti jih zapovedal ta dan,',
        12: 'da se ne bi, ko se naješ in si sit in si si zgradil ljubke hiše in prebival v njih;',
        13: 'in ko se tvoji tropi in tvoje črede pomnožijo in je pomnoženo tvoje srebro in tvoje zlato in je pomnoženo vse, kar imaš;',
        14: 'tvoje srce ne povzdigne in pozabiš na Gospoda, svojega Boga, ki te je privedel iz egiptovske dežele, iz hiše sužnosti,',
        15: 'ki te je vodil skozi to veliko in strašno divjino, v kateri so bile ognjene kače, škorpijoni in suša, kjer ni bilo vode; ki ti je vodo privedel iz kremenčeve skale;',
        16: 'ki te je v divjini hranil z mano, ki je tvoji očetje niso poznali, da bi te lahko ponižal in da bi te lahko preizkusil, da ti v tvojem zadnjem koncu stori dobro.',
        17: 'In ti bi rekel v svojem srcu: ›Moja moč in mogočnost moje roke mi je pridobila to premoženje.‹',
        18: 'Ampak se boš spominjal Gospoda, svojega Boga, kajti on je ta, ki ti daje moč, da pridobiš premoženje, da lahko on vzpostavi svojo zavezo, ki jo je prisegel tvojim očetom, kakor je to ta dan.',
        19: 'Zgodilo pa se bo, če pozabite Gospoda, svojega Boga in hodite za drugimi bogovi in jim služite in jih obožujete, ta dan pričujem zoper vas, se boste zagotovo pogubili.',
        20: 'Kakor narodi, ki jih Gospod uničuje pred vašim obrazom, tako se boste pogubili, ker niste hoteli biti poslušni glasu Gospoda, svojega Boga.',
    },
    9: {
        1: 'Poslušaj, oh Izrael: ›Danes prečkaš Jordan, da vstopiš in vzameš v last narode, večje in močnejše kakor ti, velika mesta in ograjena do neba,',
        2: 'veliko in visoko ljudstvo, otroke Anákovcev, ki jih poznaš in o katerih si slišal reči: ›Kdo lahko stoji pred Anákovimi otroki!‹',
        3: 'Razumi torej ta dan, da je Gospod, tvoj Bog, tisti, ki gre preko pred teboj. Kakor požirajoč ogenj jih bo uničil in on jih bo privedel dol, pred tvoj obraz. Tako jih boš pognal ven in jih hitro uničil, kakor ti je rekel Gospod.',
        4: 'Ne govori v svojem srcu, potem ko jih je Gospod, tvoj Bog, spodil izpred tebe, rekoč: ›Zaradi moje pravičnosti me je Gospod privedel, da vzamem v last to deželo,‹ temveč jih je zaradi zlobnosti teh narodov Gospod pognal izpred tebe.',
        5: 'Ne greš, da zaradi svoje pravičnosti ali zaradi poštenosti svojega srca vzameš v last njihovo deželo, temveč zaradi zlobnosti teh narodov jih je Gospod, tvoj Bog, pognal izpred tebe in da lahko izpolni besedo, ki jo je Gospod prisegel tvojim očetom, Abrahamu, Izaku in Jakobu.',
        6: 'Razumi torej, da ti Gospod, tvoj Bog, te dobre zemlje ne daje v posest zaradi tvoje pravičnosti, kajti ti si trdovratno ljudstvo.',
        7: 'Zapomni si in ne pozabi, kako si v divjini do besa dražil Gospoda, svojega Boga. Od dneva, ko si odšel iz egiptovske dežele, dokler niste prišli na ta kraj, ste bili uporni zoper Gospoda.',
        8: 'Tudi na Horebu ste do besa izzivali Gospoda, tako da je bil Gospod nad vami jezen, da vas uniči.',
        9: 'Ko sem odšel gor na goro, da prejmem kamniti plošči, torej plošči zaveze, ki jo je Gospod sklenil z vami, potem sem na gori ostal štirideset dni in štirideset noči niti nisem jedel kruha niti pil vode.',
        10: 'In Gospod mi je izročil dve kamniti plošči, popisani z Božjim prstom. Na njima je bilo napisano glede na vse besede, ki jih je Gospod z vami govoril na gori, iz srede ognja, na dan zbora.',
        11: 'Ob koncu štiridesetih dni in štiridesetih noči se je pripetilo, da mi je Gospod dal dve kamniti plošči, torej plošči zaveze.',
        12: 'Gospod mi je rekel: ›Vstani, hitro se spusti od tod, kajti tvoje ljudstvo, ki si jih privedel iz Egipta, se je izpridilo. Hitro so se obrnili proč iz poti, ki sem jim jo zapovedal. Naredili so si ulito podobo.‹',
        13: 'Nadalje mi je Gospod spregovoril, rekoč: ›Videl sem to ljudstvo in glej, to je trdovratno ljudstvo.',
        14: 'Pusti me pri miru, da jih lahko uničim in njihovo ime izbrišem izpod neba. Iz tebe pa bom naredil narod, mogočnejši in večji kakor oni.‹',
        15: 'Tako sem se obrnil in prišel dol z gore in gora je gorela z ognjem in dve tabli zaveze sta bili v mojih dveh rokah.',
        16: 'Pogledal sem in glej, grešili ste zoper Gospoda, svojega Boga in si naredili ulito tele. Hitro ste se obrnili proč iz poti, ki vam jo je zapovedal Gospod.',
        17: 'Vzel sem dve plošči in ju vrgel iz svojih dveh rok ter ju razbil pred vašimi očmi.',
        18: 'In padel sem dol pred Gospodom, kakor prvič, štirideset dni in štirideset noči. Niti nisem jedel kruha niti nisem pil vode zaradi vseh vaših grehov, ki ste jih z zlobnim početjem zagrešili v Gospodovih očeh, da ga izzivate k jezi.',
        19: 'Kajti bal sem se jeze in silnega nezadovoljstva, s katerim je bil Gospod ogorčen zoper vas, da vas uniči. Toda Gospod mi je tudi ob tistem času prisluhnil.',
        20: 'Gospod je bil zelo jezen nad Aronom, da bi ga uničil, jaz pa sem isti čas molil za Arona.',
        21: 'Vzel sem vaš greh, tele, ki ste ga naredili in ga sežgal z ognjem in ga poteptal in ga zelo drobno zmlel, dokler ni bil ta majhen kakor prah, in njegov prah sem vrgel v potok, ki se spušča z gore.',
        22: 'In pri Tabêri, pri Masi in pri Kibrot-Hattaavi ste do besa izzivali Gospoda.',
        23: 'Podobno, ko vas je Gospod poslal iz Kadeš Barnée, rekoč: ›Pojdite gor in vzemite v last deželo, ki sem vam jo dal.‹ Potem ste se uprli zoper zapoved Gospoda, svojega Boga in mu niste verjeli niti niste prisluhnili njegovemu glasu.',
        24: 'Od dneva, ko sem vas spoznal, ste bili uporni zoper Gospoda.',
        25: 'Tako sem padel dol pred Gospodom, štirideset dni in štirideset noči, kakor sem prvič padel dol, ker je Gospod rekel, da vas bo uničil.',
        26: 'Molil sem torej h Gospodu in rekel: ›Oh Gospod Bog, ne uniči svojega ljudstva in svoje dediščine, ki si jo odkupil preko svoje veličine, ki si jo s svojo mogočno roko privedel iz Egipta.',
        27: 'Spomni se svojih služabnikov: Abrahama, Izaka in Jakoba. Ne glej na trmoglavost teh ljudi niti k njihovi zlobnosti niti k njihovemu grehu,',
        28: 'da ne bi dežela, od koder si nas privedel, rekla: ›Ker jih Gospod ni bil zmožen privesti v deželo, ki jim jo je obljubil in ker jih je sovražil, jih je privedel ven, da jih pobije v divjini.‹',
        29: 'Vendar so tvoje ljudstvo in tvoja dediščina, ki si jih izpeljal s svojo mogočno močjo in s svojim iztegnjenim laktom.‹',
    },
    10: {
        1: 'Ob tistem času mi je Gospod rekel: ›Izsekaj si dve kamniti plošči, podobni prvima in pridi gor k meni na goro in si naredi skrinjo iz lesa.',
        2: 'Na tabli bom zapisal besede, ki so bile na prvih tablah, ki si ju razbil in položil ju boš v skrinjo.‹',
        3: 'In naredil sem skrinjo iz akacijevega lesa in izsekal dve kamniti plošči, podobni prvima in odšel gor na goro in v svoji roki sem imel dve tabli.',
        4: 'Na tabli je zapisal deset zapovedi, glede na prvo pisanje, ki vam jih je Gospod govoril na gori iz srede ognja na dan zbora. In Gospod mi ju je dal.',
        5: 'Obrnil sem se in prišel dol z gore in tabli položil v skrinjo, ki sem jo naredil, in tam sta, kakor mi je Gospod zapovedal.',
        6: 'Izraelovi otroci so odšli na svoje potovanje od Beeróta Jaakánovih otrok v Mosêro. Tam je Aron umrl in tam je bil pokopan in namesto njega je v duhovniški službi služil njegov sin Eleazar.',
        7: 'Od tam so odpotovali v Gidgád in iz Gidgáda v Jotbáto, deželo rek vodá.',
        8: 'Ob tistem času je Gospod ločil Lévijev rod, da nosi skrinjo Gospodove zaveze, da stojijo pred Gospodom, da mu služijo in da blagoslavljajo v njegovem imenu, do današnjega dne.',
        9: 'Zato Levi nima deleža niti dediščine s svojimi brati; Gospod je njegova dediščina, kakor mu je obljubil Gospod, tvoj Bog.',
        10: 'In ostal sem na gori, kakor prvič, štirideset dni in štirideset noči in Gospod mi je prisluhnil tudi ob tistem času in Gospod te ni hotel uničiti.',
        11: 'Gospod mi je rekel: ›Vstani, odpravi se na svoje potovanje pred ljudstvom, da lahko vstopijo in vzamejo v last deželo, ki sem jo prisegel njihovim očetom, da jim jo dam.‹',
        12: 'In sedaj, Izrael, kaj Gospod, tvoj Bog, zahteva od tebe, razen, da se bojiš Gospoda, svojega Boga, da hodiš po vseh njegovih poteh, da ga ljubiš, da služiš Gospodu, svojemu Bogu, z vsem svojim srcem in z vso svojo dušo.',
        13: 'Da varuješ Gospodove zapovedi in njegove zakone, ki ti jih ta dan zapovedujem v tvoje dobro?',
        14: 'Glej, nebo in nebesa nebes so od Gospoda, tvojega Boga, tudi zemlja z vsem, kar je na njej.',
        15: 'Samo Gospod je imel zadovoljstvo v tvojih očetih, da jih vzljubi in izbral je njihovo seme za njimi, torej vas, izmed vseh ljudstev, kakor je to ta dan.',
        16: 'Obrežite torej prednjo kožico svojega srca in ne bodite več trdovratni.',
        17: 'Kajti Gospod, vaš Bog, je Bog bogov in Gospod gospodov in véliki Bog, mogočen in strašen, ki se ne ozira na osebe niti ne sprejema nagrade.',
        18: 'Izvaja sodbo sirote in vdove in ljubi tujca v tem, da mu daje hrano in oblačilo.',
        19: 'Ljubite torej tujca, kajti tujci ste bili v egiptovski deželi.',
        20: 'Bal se boš Gospoda, svojega Boga. Njemu boš služil in k njemu se boš trdno pridružil in prisegal pri njegovem imenu.',
        21: 'On je tvoja hvala in on je tvoj Bog, ki je zate storil te velike in strašne stvari, ki so jih videle tvoje oči.',
        22: 'Tvoji očetje so odšli dol v Egipt s sedemdesetimi osebami in sedaj te je Gospod, tvoj Bog, naredil kakor zvezd neba zaradi množice.',
    },
    11: {
        1: 'Zato boš torej ljubil Gospoda, svojega Boga in dnevno ohranjal njegovo zadolžitev, njegove zakone, njegove sodbe in njegove zapovedi.',
        2: 'In vedi ta dan, kajti nisem govoril z otroki, ki niso vedeli in ki niso videli kaznovanja Gospoda, svojega Boga, njegove veličine, njegove mogočne roke, njegovega iztegnjenega lakta,',
        3: 'njegovih čudežev in njegovih dejanj, ki jih je v sredi Egipta storil faraonu, egiptovskemu kralju in vsej njegovi deželi',
        4: 'in kaj je on storil egiptovski vojski, njihovim konjem in njihovim bojnim vozovom; kako je vodo Rdečega morja primoral, da jih preplavi, medtem ko so vas zasledovali in kako jih je Gospod uničil do današnjega dne,',
        5: 'in kaj vam je storil v divjini, dokler niste prišli na ta kraj,',
        6: 'in kaj je storil Datánu in Abirámu, sinovoma Rubenovega sina Eliába; kako je zemlja odprla svoja usta in požrla njiju, njune družine, njune šotore in vse njuno imetje, ki je bilo v njuni posesti, v sredi vsega Izraela,',
        7: 'toda vaše oči so videle vsa velika Gospodova dejanja, ki jih je storil.',
        8: 'Zatorej boste ohranjali vse zapovedi, ki sem vam jih ta dan zapovedal, da boste lahko močni in vstopite in se polastite dežele, kamor greste, da jo vzamete v last',
        9: 'in da boste lahko podaljšali svoje dneve v deželi, ki jo je Gospod prisegel vašim očetom, da jo da njim in njihovemu semenu, deželo, kjer tečeta mleko in med.',
        10: 'Kajti dežela, kamor vstopaš, da jo vzameš v last, ni kakor egiptovska dežela, od koder ste izšli, kjer si sejal svoje seme in jo s svojim stopalom namakal kakor zeliščni vrt,',
        11: 'temveč je dežela, kamor greste, da jo vzamete v last, dežela hribov in dolin in pitne vode od dežja z neba,',
        12: 'dežela, za katero skrbi Gospod, tvoj Bog; oči Gospoda, tvojega Boga, so vedno na njej, od začetka leta, celó do konca leta.',
        13: 'In zgodilo se bo, če boste marljivo prisluhnili mojim zapovedim, ki sem vam jih ta dan zapovedal, da ljubite Gospoda, svojega Boga in da mu služite z vsem svojim srcem in z vso svojo dušo,',
        14: 'da vam bom dal dežja vaši deželi v njegovem pravšnjem obdobju, prvi dež in pozni dež, da boš lahko zbral svoje žito in svoje vino in svoje olje.',
        15: 'In poslal bom travo na tvoja polja za tvojo živino, da boš lahko jedel in bil sit.',
        16: 'Pazite nase, da vaše srce ne bo zavedeno in se odvrnete in služite drugim bogovom in jih obožujete',
        17: 'in bi se potem zoper vas vžgal Gospodov bes in on zapre nebo, da tam ne bo dežja in da dežela ne obrodi svojega sadu in da se ne bi hitro pogubili iz dobre dežele, ki vam jo daje Gospod.',
        18: 'Zatorej boste te moje besede položili v svoje srce in v svojo dušo in si jih privezali za znamenje na roko, da bodo lahko kakor načelki med vašimi očmi.',
        19: 'In vi jih boste učili svoje otroke, govoreč o njih, ko sediš v svoji hiši in ko hodiš po poti, ko se uležeš in ko vstajaš.',
        20: 'Napisal jih boš na podboje svoje hiše in na svoja velika vrata,',
        21: 'da bodo vaši dnevi lahko pomnoženi in dnevi vaših otrok v deželi, ki jo je Gospod prisegel vašim očetom, da jim jo da, kakor dneve nebes na zemlji.',
        22: 'Kajti če boste marljivo varovali vse te zapovedi, ki sem vam jih zapovedal, da jih storite, da ljubite Gospoda, svojega Boga, da hodite po vseh njegovih poteh in da se ga trdno držite,',
        23: 'potem bo Gospod vse te narode izgnal izpred vas in vi se boste polastili večjih narodov in mogočnejših, kakor ste vi.',
        24: 'Vsak kraj, na katerega bodo stopili podplati vaših stopal, bo vaš; od divjine in Libanona, od reke, reke Evfrata, celo do najbolj oddaljenega morja bo vaša pokrajina.',
        25: 'Tam noben človek ne bo mogel obstati pred vami, kajti Gospod, vaš Bog, bo položil strah pred vami in grozo nad vso deželo, po kateri boste stopali, kakor vam je rekel.',
        26: 'Glejte, ta dan sem pred vas postavil blagoslov in prekletstvo.',
        27: 'Blagoslov, če ubogate zapovedi Gospoda, svojega Boga, ki sem vam jih ta dan zapovedal',
        28: 'in prekletstvo, če ne boste ubogali zapovedi Gospoda, svojega Boga, temveč se boste odvrnili iz poti, ki sem vam jo ta dan zapovedal, da greste za drugimi bogovi, ki jih niste poznali.',
        29: 'In zgodilo se bo, ko te bo Gospod, tvoj Bog, privedel v deželo, kamor greš, da jo vzameš v last, da boš položil blagoslov na goro Garizím in prekletstvo na goro Ebál.',
        30: 'Ali nista na drugi strani Jordana, ob poti, kjer sonce zahaja v kánaanski deželi, ki prebivajo v nerodovitni ravnini nasproti Gilgálu, poleg Moréjevih ravnin?',
        31: 'Kajti šli boste čez Jordan, da vstopite, da vzamete v last deželo, ki vam jo daje Gospod, vaš Bog in vzeli jo boste v last in prebivali v njej.',
        32: 'In obeležili boste, da storite vse zakone in sodbe, ki sem jih ta dan postavil pred vas.',
    },
    12: {
        1: 'To so zakoni in sodbe, ki jih boste obeležili, da jih počnete v deželi, ki ti jo daje Gospod, Bog vaših očetov, da jo vzamete v last, vse dni, ko živite na zemlji.',
        2: 'Vse kraje, na katerih so narodi, ki jih boste vzeli v last, služili svojim bogovom na visokih gorah, na hribih in pod vsakim zelenim drevesom, boste popolnoma uničili.',
        3: 'Porušili boste njihove oltarje, zlomili njihove stebre, njihove ašere sežgali z ognjem, posekali boste rezane podobe njihovih bogov in njihova imena uničili iz tega kraja.',
        4: 'Tako ne boste storili Gospodu, svojemu Bogu.',
        5: 'Toda na kraj, ki ga bo Gospod, vaš Bog, izbral izmed vseh vaših rodov, da tam položi svoje ime, celó k njegovemu prebivališču boste sledili in tja boš prišel',
        6: 'in tja boste prinašali svoje žgalne daritve, svoje klavne daritve, svoje desetine, vzdigovalne daritve svoje roke, svoje zaobljube, svoje prostovoljne daritve in prvence od svojih čred in od svojih tropov.',
        7: 'Tam boste jedli pred Gospodom, svojim Bogom in veselili se boste v vsem, k čemur položite svojo roko, vi in vaše družine, v čemer te je Gospod, tvoj Bog, blagoslovil.',
        8: 'Ne boste počeli po vseh stvareh, ki jih mi ta dan delamo tukaj, vsak mož karkoli je pravilno v njegovih lastnih očeh.',
        9: 'Kajti doslej niste prišli k počitku in k dediščini, ki vam jo daje Gospod, vaš Bog.',
        10: 'Toda ko greste čez Jordan in prebivate v deželi, ki vam jo daje Gospod, vaš Bog, da jo podedujete in ko vam daje počitek pred vsemi vašimi sovražniki naokoli, tako da varno prebivate,',
        11: 'potem bo tam kraj, ki ga bo Gospod, vaš Bog, izbral, da svojemu imenu povzroči, da prebiva tam. Tja boste prinesli vse, kar sem vam zapovedal: vaše žgalne daritve, vaše klavne daritve, vaše desetine, vzdigovalno daritev vaše roke in vso vašo izbiro zaobljub, ki ste jih zaobljubili Gospodu,',
        12: 'in veselili se boste pred Gospodom, vašim Bogom, vi in vaši sinovi, vaše hčere, služabniki, vaše dekle in Lévijevec, ki je znotraj tvojih velikih vrat, ker nima ne deleža, ne dediščine z vami.',
        13: 'Pazi nase, da ne daruješ svojih žgalnih daritev na vsakem kraju, ki ga vidiš,',
        14: 'temveč na kraju, ki ga bo Gospod izbral v enem izmed tvojih rodov, tam boš daroval svoje žgalne daritve in tam boš počel vse, kar ti zapovem.',
        15: 'Vendar v vseh svojih velikih vratih lahko zakolješ in ješ meso, karkoli tvoja duša poželi, glede na blagoslov Gospoda, tvojega Boga, ki ti ga je dal. Nečisti in čisti lahko jé od tega, kakor od srnjaka in kakor od jelena.',
        16: 'Samo krvi ne boste jedli; kakor vodo jo boste izlili na zemljo.',
        17: 'Znotraj svojih velikih vrat ne smeš jesti desetine svojega žita ali svojega vina ali svojega olja ali prvencev svojih čred ali svojega tropa, niti česarkoli od svojih zaobljub, ki si jih zaobljubil, niti svojih prostovoljnih daritev ali vzdigovalne daritve svoje roke,',
        18: 'temveč jih moraš jesti pred Gospodom, svojim Bogom, na kraju, ki ga bo Gospod, tvoj Bog, izbral, ti in tvoj sin, tvoja hči, tvoj sluga, tvoja dekla in Lévijevec, ki je znotraj tvojih velikih vrat, in veselil se boš pred Gospodom, svojim Bogom, v vsem, k čemur priložiš svoji roki.',
        19: 'Pazi nase, da ne zapustiš Lévijevca tako dolgo, kot živiš na zemlji.',
        20: 'Ko bo Gospod, tvoj Bog, povečal tvojo mejo, kakor ti je obljubil in boš rekel: ›Jedel bom meso,‹ ker tvoja duša hrepeni, da bi jedla meso; lahko ješ meso, karkoli tvoja duša poželi.',
        21: 'Če je kraj, ki ga je izbral Gospod, tvoj Bog, da tam položi svoje ime, predaleč od tebe, potem boš zaklal od svoje črede in od svojega tropa, ki ti ga je dal Gospod, kakor sem ti zapovedal in v svojih velikih vratih boš jedel karkoli tvoja duša poželi.',
        22: 'Celo kakor se pojesta srnjak in jelen, tako jih boš ti pojedel. Nečisti in čisti bosta enako jedla od njih.',
        23: 'Samo bodi odločen, da ne ješ krvi, kajti kri je življenje in življenja ne smeš jesti z mesom.',
        24: 'Ne boš je jedel. Kakor vodo jo boš izlil na zemljo.',
        25: 'Ne boš je jedel, da bo lahko dobro s teboj in s tvojimi otroki za teboj, ko boš delal to, kar je pravilno v Gospodovih očeh.',
        26: 'Samo svoje svete stvari, ki jih imaš in svoje zaobljube boš vzel in šel na kraj, ki ga bo Gospod izbral',
        27: 'in daroval boš svoje žgalne daritve, meso in kri, na oltarju Gospoda, svojega Boga. In kri tvojih klavnih daritev bo izlita na oltar Gospoda, tvojega Boga in jedel boš meso.',
        28: 'Obeležuj in poslušaj vse te besede, ki sem ti jih zapovedal, da bo lahko dobro s teboj in s tvojimi otroki za teboj na veke, ko delaš to, kar je dobro in pravilno v očeh Gospoda, tvojega Boga.',
        29: 'Ko bo Gospod, tvoj Bog, izpred tebe uničil narode, kamor greš, da jih vzameš v last in jih zasedeš in prebivaš v njihovi deželi,',
        30: 'pazi nase, da ne boš ujet s tem, da jim slediš, potem ko so bili uničeni izpred tebe, in da ne povprašuješ po njihovih bogovih, rekoč: ›Kako so ti narodi služili svojim bogovom? Celo jaz bom počel podobno.‹',
        31: 'Ne boš tako počel Gospodu, svojemu Bogu, kajti vsako ogabnost Gospodu, ki jo on sovraži, so počeli svojim bogovom, kajti celo svoje sinove in svoje hčere so v ognju sežigali svojim bogovom.',
        32: 'Katerokoli stvar ti zapovem, obeležuj, da jo storiš. K temu ne boš dodal niti od tega ne boš jemal.',
    },
    13: {
        1: 'Če tam med vami vstane prerok ali sanjač sanj in ti daje znamenje ali čudež',
        2: 'in se znamenje ali čudež, o katerem ti je govoril zgodi, rekoč: ›Pojdimo za drugimi bogovi, ki jih nisi poznal in jim služimo,‹',
        3: 'ne boš prisluhnil besedam tega preroka ali tega sanjača sanj, kajti Gospod, vaš Bog, vas preizkuša, da bi spoznal ali ljubite Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo.',
        4: 'Hodili boste za Gospodom, svojim Bogom in se ga bali in varovali njegove zapovedi in ubogali njegov glas in mu boste služili in se trdno pridružili k njemu.',
        5: 'Tisti prerok ali tisti sanjač sanj pa bo usmrčen, zato ker je govoril, da vas odvrne od Gospoda, vašega Boga, ki vas je privedel iz egiptovske dežele in vas odkupil iz hiše sužnosti, da bi te sunil iz poti, ki ti jo je Gospod, tvoj Bog, zapovedal, da hodiš po njej. Tako boš zlo iztrebil proč iz svoje srede.',
        6: 'Če te tvoj brat, sin tvoje matere ali tvoj sin ali tvoja hči ali žena tvojega naročja ali tvoj prijatelj, ki je kakor tvoja lastna duša, na skrivaj privabi, rekoč: ›Pojdimo in služimo drugim bogovom,‹ ki jih nisi poznal ne ti niti tvoji očetje,',
        7: 'namreč bogovom ljudstev, ki so naokoli tebe, blizu tebe ali daleč od tebe, od enega konca zemlje celo do drugega konca zemlje,',
        8: 'se ne boš strinjal z njim, niti mu prisluhnil, niti se ga tvoje oko ne bo usmililo, niti ne boš prizanesel, niti mu ne boš prikrival,',
        9: 'temveč ga boš zagotovo ubil. Tvoja roka bo prva nad njim, da ga položi v smrt in zatem roka vsega ljudstva.',
        10: 'Kamnal ga boš s kamni, da umre, ker je iskal, da te pahne proč od Gospoda, tvojega Boga, ki te je privedel iz egiptovske dežele, iz hiše sužnosti.',
        11: 'In ves Izrael bo slišal in se bal in nobene takšne zlobnosti, kot je ta, ne bo več storil med vami.',
        12: 'Če boš slišal reči v enem izmed svojih mest, ki ti jih je Gospod, tvoj Bog, dal, da prebivaš tam, rekoč:',
        13: '› Neki možje, Beliáovi otroci, so odšli ven izmed vas in zavedli prebivalce svojega mesta, rekoč: ›Pojdimo in služimo drugim bogovom,‹ ki jih niste poznali.‹',
        14: 'Potem boš povprašal in naredil preiskavo in marljivo spraševal, in glej, če je to res in je stvar gotova, da je med vami narejena takšna ogabnost,',
        15: 'potem boš prebivalce tega mesta zagotovo udaril z ostrino meča, ga skrajno uničil in vse, kar je v njem in njegovo živino, z ostrino meča.',
        16: 'Ves njegov plen boš zbral na sredi njegove ulice in mesto popolnoma sežgal z ognjem in ves njegov plen, za Gospoda, svojega Boga, in le-to bo kup na veke; ne bo ponovno zgrajeno.',
        17: 'Tvoje roke se ne bo trdno pridružilo ničesar od preklete stvari, da se bo Gospod lahko odvrnil od okrutnosti svoje jeze in ti izkazal usmiljenje in imel sočutje nad teboj in te pomnožil, kakor je prisegel tvojim očetom,',
        18: 'ko boš prisluhnil glasu Gospoda, svojega Boga, da varuješ vse njegove zapovedi, ki sem ti jih ta dan ukazal, da delaš to, kar je pravilno v očeh Gospoda, svojega Boga.',
    },
    14: {
        1: 'Vi ste otroci Gospoda, svojega Boga. Ne boste se rezali niti naredili katerekoli plešavosti med svojimi očmi zaradi mrtvega.',
        2: 'Kajti ti si sveto ljudstvo Gospoda, svojega Boga in Gospod te je izbral, da bi mu bil izvoljeno ljudstvo nad vsemi narodi, ki so na zemlji.',
        3: 'Ne boš jedel kakršnekoli gnusne stvari.',
        4: 'To so živali, ki jih boš jedel: vol, ovca, koza,',
        5: 'jelen, srnjak, damjak, divja koza, antilopa, divji vol in gams.',
        6: 'Vsako žival, ki deli kopito in ima parklje razklane na dvoje in prežvekuje med živalmi, to boste jedli.',
        7: 'Vendar teh ne boste jedli izmed teh, ki prežvekujejo ali izmed teh, ki delijo kopito, kot so kamela, zajec in kunec, kajti prežvekujejo, toda ne delijo kopita, zato so vam nečiste.',
        8: 'In svinjo, ker ta deli kopito, vendar ne prežvekuje, ta vam je nečista. Ne boste jedli od njihovega mesa niti se ne boste dotaknili njihovega mrtvega trupla.',
        9: 'Te boste jedli od vsega, kar je v vodah: jedli boste vse, ki imajo plavuti in luske.',
        10: 'Karkoli pa nima plavuti in lusk ne smete jesti, to vam je nečisto.',
        11: 'Jedli boste od vseh čistih ptic.',
        12: 'Toda ti so tisti, od katerih ne boste jedli: orel, brkati ser, ribji orel,',
        13: 'črni škarnik, kragulj, jastreb po njegovi vrsti,',
        14: 'vsak krokar po njegovi vrsti,',
        15: 'sova, nočni sokol, kukavica, sokol po njegovi vrsti,',
        16: 'majhna sova, velika sova, labod,',
        17: 'pelikan, egiptovski jastreb, kormoran,',
        18: 'štorklja, čaplja po svoji vrsti, smrdokavra in netopir.',
        19: 'Vsaka plazeča stvar, ki leti, vam je nečista, teh naj se ne jé.',
        20: 'Toda od vse čiste perjadi lahko jeste.',
        21: 'Od nobene stvari, ki pogine sama od sebe, ne boste jedli. Dal jo boš tujcu, ki je v tvojih velikih vratih, da bo to lahko jedel, oziroma jo lahko prodaš neznancu, kajti ti si sveto ljudstvo Gospodu, svojemu Bogu. Kozlička ne boš kuhal v mleku njegove matere.',
        22: 'Resnično boš desetinil ves donos svojega semena, ki ti ga polje prinaša leto za letom.',
        23: 'Pred Gospodom, svojim Bogom, na kraju, ki ga je on izbral, da tam namesti svoje ime, boš jedel desetino svojega žita, svojega vina, svojega olja in prvence svojih čred in svojih tropov, da se lahko naučiš vedno bati se Gospoda, svojega Boga.',
        24: 'Če pa je pot zate predolga, tako da tega ne moreš nesti, ali če je kraj, ki ga bo Gospod, tvoj Bog, izbral, da tam postavi svoje ime, predaleč od tebe, ko te je Gospod, tvoj Bog, blagoslovil,',
        25: 'potem boš to spremenil v denar in denar povezal v svojo roko in boš šel na kraj, ki ga bo Gospod, tvoj Bog, izbral,',
        26: 'in ti boš ta denar dal, za karkoli tvoja duša poželi. Za vole ali za ovce ali za vino ali za močno pijačo ali za karkoli, kar tvoja duša poželi in jedel boš tam pred Gospodom, svojim Bogom in veselil se boš ti in tvoja družina',
        27: 'in Lévijevec, ki je znotraj tvojih velikih vrat. Ne boš ga zapustil, kajti on nima niti deleža niti dediščine s teboj.',
        28: 'Ob koncu treh let boš prinesel vso desetino svojega pridelka istega leta in to boš položil znotraj svojih velikih vrat',
        29: 'in Lévijevec (ker nima niti deleža niti dediščine s teboj) in tujec, sirota in vdova, ki so znotraj tvojih velikih vrat, bodo prišli, jedli in bodo nasičeni, da te Gospod, tvoj Bog, lahko blagoslovi pri vsem delu tvoje roke, ki ga počneš.',
    },
    15: {
        1: 'Ob koncu vsakih sedmih let boš naredil odpust.',
        2: 'To je način odpusta. Vsak upnik, ki posoja, mora svojemu bližnjemu to odpustiti. Tega ne bo terjal od svojega bližnjega ali od svojega brata, ker je to imenovano Gospodov odpust.',
        3: 'Od tujca lahko to ponovno zahtevaš, toda kar je tvoje, s tvojim bratom, bo tvoja roka odpustila,',
        4: 'razen ko med vami ne bo nobenega revnega, kajti Gospod te bo silno blagoslovil v deželi, ki ti jo daje Gospod, tvoj Bog, za dediščino, da jo vzameš v last,',
        5: 'samo če previdno prisluhneš glasu Gospoda, svojega Boga, da obeležuješ izpolnjevanje vseh teh zapovedi, ki sem ti jih ta dan zapovedal.',
        6: 'Kajti Gospod, tvoj Bog, te blagoslavlja, kakor ti je obljubil in posojal boš mnogim narodom, toda ti si ne boš izposojal in kraljeval boš nad mnogimi narodi, toda oni ne bodo kraljevali nad teboj.',
        7: 'Če je med vami revež enega izmed tvojih bratov znotraj katerihkoli izmed tvojih velikih vrat, v tvoji deželi, ki ti jo daje Gospod, tvoj Bog, ne boš zakrknil svojega srca niti svoje roke zaprl pred svojim revnim bratom,',
        8: 'temveč mu boš na široko odprl svojo roko in zagotovo mu boš posodil dovolj za njegovo potrebo, v tem, kar mu manjka.',
        9: 'Pazi se, da ne bi bilo misli v tvojem zlobnem srcu, rekoč: ›Sedmo leto, leto odpusta, se približuje‹ in je tvoje oko zlobno zoper tvojega revnega brata in mu ničesar ne daš in on zoper tebe kliče h Gospodu in to ti bo greh.',
        10: 'Zagotovo mu boš dal in tvoje srce ne bo užaloščeno, ko mu daješ, zato ker te bo za to stvar Gospod, tvoj Bog, blagoslovil v vseh tvojih delih in v vsem, k čemur boš položil svojo roko.',
        11: 'Kajti revni ne bo nikoli izginil iz dežele. Zatorej ti zapovedujem, rekoč: ›Svojo roko boš na široko odprl svojem bratu, svojemu revnemu in svojemu pomoči potrebnemu v svoji deželi.‹',
        12: 'In če ti bo prodan tvoj brat, Hebrejec ali Hebrejka in ti služi šest let, ga boš potem v sedmem letu od sebe pustil svobodnega.',
        13: 'In ko ga svobodnega pošlješ od sebe, mu ne boš pustil, da gre proč prazen.',
        14: 'Velikodušno ga boš opremil iz svojega tropa in iz svojega mlatišča in iz svoje vinske stiskalnice. Dal mu boš od tega, s čimer te je Gospod, tvoj Bog, blagoslovil.',
        15: 'Spomnil se boš, da si bil suženj v egiptovski deželi in Gospod, tvoj Bog, te je odkupil, zato ti danes zapovedujem to stvar.',
        16: 'Zgodilo se bo, če ti reče: ›Ne bom šel proč od tebe,‹ ker ljubi tebe in tvojo hišo, ker mu je dobro s teboj,',
        17: 'potem boš vzel šilo in ga na vratih prebodel skozi njegovo uho in on bo tvoj služabnik na veke. In prav tako boš podobno storil svoji dekli.',
        18: 'Ne bo se ti zdelo težko, ko ga svobodnega pošlješ proč od sebe, kajti vreden ti je bil dvojnega najetega služabnika, v tem, ko ti je služil šest let in Gospod, tvoj Bog, te bo blagoslovil v vsem, kar delaš.',
        19: 'Vse prvence, ki pridejo iz tvoje črede in iz tvojega tropa, boš posvetil Gospodu, svojemu Bogu. Nobenega dela ne boš opravljal s prvencem svojega bikca niti strigel prvenca svoje ovce.',
        20: 'To boš leto za letom jedel pred Gospodom, svojim Bogom, ti in tvoja družina, na kraju, ki ga bo Gospod izbral.',
        21: 'In če je na njem kakršnakoli pomanjkljivost kakor, če je hrom ali slep ali ima kakršnokoli bolezensko pomanjkljivost, ga ne boš žrtvoval Gospodu, svojemu Bogu.',
        22: 'Jedel ga boš znotraj svojih velikih vrat. Nečista in čista oseba ga bo jedla enako kakor srnjaka in kakor jelena.',
        23: 'Samo njegove krvi ne boš jedel. Na tla jo boš izlil kakor vodo.',
    },
    16: {
        1: 'Obeležujte mesec abíb in praznujte pasho Gospodu, svojemu Bogu, kajti v mesecu abíbu te je Gospod, tvoj Bog, ponoči privedel iz Egipta.',
        2: 'Torej boš žrtvoval pasho Gospodu, svojemu Bogu, od tropa in črede, na kraju, ki ga bo Gospod, tvoj Bog, izbral, da tam postavi njegovo ime.',
        3: 'Zraven ne boš jedel nobenega kvašenega kruha. Sedem dni boš zraven jedel nekvašen kruh, celo kruh stiske, kajti v naglici si prišel iz egiptovske dežele, da se vse dni svojega življenja lahko spominjaš dneva, ko si prišel ven iz egiptovske dežele.',
        4: 'S teboj, v vseh tvojih pokrajinah, sedem dni ne bo videti nobenega kvašenega kruha niti naj tam ne ostane nobene stvari od mesa, ki ga žrtvuješ zvečer prvega dne, čez noč do jutra.',
        5: 'Ne smeš žrtvovati pashe, ki ti jo daje Gospod, tvoj Bog, znotraj katerihkoli izmed tvojih velikih vrat,',
        6: 'temveč na kraju, ki ti ga bo Gospod, tvoj Bog, izbral, da tja postavi svoje ime, tam boš zvečer žrtvoval pasho ob sončnem zahodu, ob času, ko si prišel ven iz Egipta.',
        7: 'To boš spekel in jedel na kraju, ki ga bo izbral Gospod, tvoj Bog. Zjutraj pa se boš obrnil in šel v svoje šotore.',
        8: 'Šest dni boš jedel nekvašen kruh in na sedmi dan bo slovesen zbor Gospodu, tvojemu Bogu. V tem [dnevu] ne boš opravljal nobenega dela.',
        9: 'Sedem tednov si boš štel, začni šteti sedem tednov od tistega časa, ko v žito začenjaš postavljati srp.',
        10: 'Praznik tednov Gospodu, svojemu Bogu, boš ohranjal z obiljem prostovoljne daritve svoje roke, ki jo boš dal Gospodu, svojemu Bogu, glede na to, kakor te je Gospod, tvoj Bog, blagoslovil.',
        11: 'Veselil se boš pred Gospodom, svojim Bogom, ti in tvoj sin, tvoja hči, tvoj sluga, tvoja dekla, Lévijevec, ki je znotraj tvojih velikih vrat, in tujec, sirota ter vdova, ki so med vami, na mestu, ki ga bo Gospod, tvoj Bog, izbral, da tam postavi svoje ime.',
        12: 'Spominjal se boš, da si bil suženj v Egiptu in obeleževal in izvajal boš vse te zakone.',
        13: 'Sedem dni boš obeleževal šotorski praznik, potem ko si spravil svoje žito in svoje vino.',
        14: 'Ob svojem prazniku se boš veselil ti in tvoj sin, tvoja hči, tvoj sluga, tvoja dekla, Lévijevec in tujec, sirota ter vdova, ki so znotraj tvojih velikih vrat.',
        15: 'Sedem dni boš praznoval slovesen praznik Gospodu, svojemu Bogu, na mestu, ki ga bo Gospod izbral, ker te bo Gospod, tvoj Bog, blagoslovil pri vsem tvojem donosu in v vseh delih tvojih rok, zato se boš zagotovo veselil.',
        16: 'Trikrat letno se bodo vsi tvoji možje prikazali pred Gospodom, tvojim Bogom, na kraju, ki ga bo izbral. Na praznik nekvašenega kruha, na praznik tednov in na šotorski praznik. Pred Gospodom se ne bodo prikazali prazni.',
        17: 'Vsak moški bo dal, kakor je zmožen, glede na blagoslov Gospoda, tvojega Boga, ki ti ga je dal.',
        18: 'Znotraj vseh svojih velikih vratih si boš postavil sodnike in častnike, ki ti jih daje Gospod, tvoj Bog, po tvojih rodovih in ljudstvu bodo sodili s pravično sodbo.',
        19: 'Ne boš sprevračal sodbe, ne boš se oziral na osebe niti ne boš jemal daru, kajti dar zaslepljuje oči modrega in sprevrača besede pravičnega.',
        20: 'Temu, kar je povsem pravično, boš sledil, da boš lahko živel in podedoval deželo, ki ti jo daje Gospod, tvoj Bog.',
        21: 'Ne boš si sadil nasada kakršnihkoli dreves blizu oltarja Gospoda, svojega Boga, ki si ga boš naredil.',
        22: 'Niti si ne boš postavljal kakršnekoli podobe; kar Gospod, tvoj Bog, sovraži.',
    },
    17: {
        1: 'Gospodu, svojemu Bogu, ne boš žrtvoval nobenega bika ali ovce, na kateri je pomanjkljivost ali kakršnakoli slaba stvar, kajti to je ogabnost Gospodu, tvojemu Bogu.',
        2: 'Če se med vami najdeta mož ali ženska, znotraj katerihkoli izmed tvojih velikih vrat, ki ti jih daje Gospod, tvoj Bog, ki sta storila zlobnost v očeh Gospoda, tvojega Boga, v tem, da sta prestopala njegovo zavezo',
        3: 'in sta šla in služila drugim bogovom in jih oboževala ali sonce ali luno ali katerokoli vojsko neba, česar nisem zapovedal',
        4: 'in ti je to povedano in si o tem slišal in marljivo poizvedoval in glej, če je resnično in je stvar gotova, da je v Izraelu narejena takšna ogabnost,',
        5: 'potem boš tega moža ali to žensko, ki sta zagrešila to zlobno stvar, pripeljal naprej, k svojim velikim vratom, torej tistega moža ali tisto žensko in ju boš kamnal s kamni, dokler ne umreta.',
        6: 'Po ustih dveh ali treh prič bo tisti, ki je vreden smrti, usmrčen, toda po ustih ene priče ne bo usmrčen.',
        7: 'Roke prič bodo prve nad njim, da ga usmrtijo in potem roke vsega ljudstva. Tako boš odstranil zlo izmed vas.',
        8: 'Če tam vstane zadeva, v sodbi zate pretežka, med krvjo in krvjo, med izgovorom in izgovorom, med udarcem in udarcem, ki so zadeve polemike znotraj tvojih velikih vrat, potem se boš vzdignil in se povzpel na kraj, ki ga bo Gospod, tvoj Bog, izbral',
        9: 'in prišel boš k duhovnikom Lévijevcem in k sodniku, ki bo v tistih dneh in povprašal in pokazali ti bodo razsodbo sodbe.',
        10: 'Storil boš glede na razsodbo, ki ti jo bodo pokazali tisti, iz tistega kraja, ki ga bo Gospod izbral in obeleževal boš, da storiš glede na vse, o čemer te obvestijo.',
        11: 'Storil boš glede na razsodbo postave, ki te jo bodo učili, in glede na sodbo, ki ti jo bodo povedali. Ne boš se odvrnil od obsodbe, ki ti jo bodo pokazali, ne na desno roko niti ne na levo.',
        12: 'Mož pa, ki bo delal prepotentno in ne bo prisluhnil duhovniku, ki tam stoji, da služi pred Gospodom, tvojim Bogom ali sodniku, celo tisti mož bo umrl, in ti se boš iz Izraela znebil zla.',
        13: 'In vse ljudstvo bo slišalo in se balo in ne bo več prepotentno ravnalo.',
        14: 'Ko prideš v deželo, ki ti jo daje Gospod, tvoj Bog in jo boš vzel v last in boš prebival v njej in boš rekel: ›Nad seboj si bom postavil kralja, kakor je pri vseh narodih naokoli mene,‹',
        15: 'boš vsekakor za kralja nad seboj postavil tistega, ki ga bo izbral Gospod, tvoj Bog. Enega izmed svojih bratov boš postavil za kralja nad seboj. Nad seboj ne smeš postaviti tujca, ki ni tvoj brat.',
        16: 'Toda ta si ne bo množil konj niti ljudstvu ne bo povzročil, da se vrne v Egipt, z namenom, da bi množil konje, ker kakor ti je Gospod rekel: ›Odslej se ne boš več vrnil po tisti poti.‹',
        17: 'Niti si k sebi ne bo množil žená, da njegovega srca ne odvrnejo stran niti k sebi ne bo silno pomnožil srebra in zlata.',
        18: 'In zgodilo se bo, ko sedi na prestolu svojega kraljestva, da si bo zapisal prepis te postave v knjigo iz te, ki je pred duhovniki Lévijevci,',
        19: 'in ta bo z njim in iz nje bo bral vse dni svojega življenja, da se bo lahko učil bati se Gospoda, svojega Boga, da ohranja vse besede te postave in te zakone, da jih izvršuje,',
        20: 'da njegovo srce ne bo povzdignjeno nad njegove brate in da se ne obrne proč od zapovedi, k desni roki ali k levi, z namenom, da lahko podaljša svoje dni v svojem kraljestvu, on in njegovi otroci, v sredi Izraela.',
    },
    18: {
        1: 'Duhovniki Lévijevci in ves Lévijev rod ne bodo imeli niti deleža niti dediščine z Izraelom. Jedli bodo Gospodove daritve, narejene z ognjem in [od] njegove dediščine.',
        2: 'Zato ne bodo imeli dediščine med svojim brati. Gospod je njihova dediščina, kakor jim je rekel.',
        3: 'In to bo pripadlo duhovniku od ljudstva, od tistih, ki darujejo klavno daritev, bodisi je to vol ali ovca; in duhovniku bodo dali pleče, dve ličnici in vamp.',
        4: 'Tudi prve sadove svojega žita, svojega vina, svojega olja in prvo runo svojih ovc mu boš dal.',
        5: 'Kajti Gospod, tvoj Bog, ga je izbral izmed vseh tvojih rodov, da stoji, da služi v Gospodovem imenu, njemu in njegovim sinovom na veke.',
        6: 'Če pride Lévijevec od katerihkoli izmed tvojih velikih vrat, ven iz vsega Izraela, kjer je začasno bival in pride z vso željo svojega uma na kraj, ki ga bo Gospod izbral,',
        7: 'potem bo služil v imenu Gospoda, svojega Boga, kakor počno vsi njegovi bratje Lévijevci, ki stojijo tam pred Gospodom.',
        8: 'Za jesti bodo imeli podobne obroke, poleg tega, kar pride od prodaje imetja njegovega očeta.',
        9: 'Ko prideš v deželo, ki ti jo daje Gospod, tvoj Bog, se ne boš naučil ravnati po gnusobah teh narodov.',
        10: 'Naj ne bo najti med vami nikogar, ki primora svojega sina ali svojo hčer, da gre skozi ogenj ali da uporablja vedeževanje ali astrologa ali uročevalca ali čarovnico',
        11: 'ali zaklinjevalca ali posvetovalca z osebnimi duhovi ali čarovnika ali rotilca duhov umrlih.',
        12: 'Kajti vsi ti, ki počno te stvari, so gnusoba Gospodu in zaradi teh gnusob jih bo Gospod, tvoj Bog, pognal izpred tebe.',
        13: 'Popoln boš z Gospodom, svojim Bogom.',
        14: 'Kajti ti narodi, ki se jih boš polastil, so poslušali astrologe in vedeževalce, toda kar se tebe tiče, ti Gospod, tvoj Bog, ni dopustil, da tako počneš.',
        15: 'Gospod, tvoj Bog, ti bo iz tvoje srede, izmed tvojih bratov, obudil Preroka, podobnega meni. Njemu boste prisluhnili,',
        16: 'glede na vse, kar si na Horebu želel od Gospoda, svojega Boga, na dan zbora, rekoč: ›Naj ne poslušam ponovno glasu Gospoda, svojega Boga niti naj ne vidim več tega velikega ognja, da ne umrem.‹',
        17: 'Gospod mi je rekel: ›Dobro so govorili to, kar so govorili.',
        18: 'Vzdignil jim bom preroka izmed njihovih bratov, podobnega tebi in svoje besede bom položil v njegova usta in govoril jim bo vse, kar mu bom zapovedal.',
        19: 'In zgodilo se bo, da kdorkoli ne bo prisluhnil mojim besedam, ki jih bo govoril v mojem imenu, bom to zahteval od njega.',
        20: 'Toda prerok, ki si bo predrznil govoriti besedo v mojem imenu, ki mu je nisem zapovedal govoriti ali ki bo govoril v imenu drugih bogov, celo ta prerok bo umrl.‹',
        21: 'In če v svojem srcu rečeš: ›Kako bomo spoznali besedo, ki je Gospod ni govoril?‹',
        22: 'Kadar prerok spregovori v Gospodovem imenu, če stvar ne sledi niti se ne zgodi, to je stvar, ki je Gospod ni rekel, temveč je prerok to prepotentno govoril. Ne boš se ga bal.',
    },
    19: {
        1: 'Kadar je Gospod, tvoj Bog, iztrebil narode, katerih deželo ti daje Gospod, tvoj Bog in jih naslediš, prebivaš v njihovih mestih in v njihovih hišah,',
        2: 'si boš v sredi svoje dežele, ki ti jo Gospod, tvoj Bog, daje v last, oddvojil tri mesta.',
        3: 'Pripravil si boš pot in na tri dele razdelil pokrajine svoje dežele, ki ti jo daje Gospod, tvoj Bog, da jo podeduješ, da lahko vsak ubijalec pobegne tja.',
        4: 'In to je primer ubijalca, ki bo pobegnil tja, da bo lahko živel: ›Kdorkoli nevede ubije svojega bližnjega, ki ga v preteklem času ni sovražil,',
        5: 'kot ko gre mož s svojim bližnjim v gozd, da sekata les in njegova roka zamahne udarec s sekiro, da poseka drevo in glava zdrsne iz toporišča in pade na njegovega bližnjega, da ta umre, bo pobegnil v eno izmed teh mest in živel,',
        6: 'da ne bi krvni maščevalec zasledoval ubijalca, medtem ko je njegovo srce vroče in ga dohitel, ker je dolga pot in ga ubil medtem ko ta ni bil vreden smrti, ker ga v preteklem času ni sovražil.',
        7: 'Zato ti zapovedujem, rekoč: ›Zase si boš oddvojil tri mesta.‹',
        8: 'Če Gospod, tvoj Bog, poveča tvojo pokrajino, kakor je prisegel tvojim očetom in ti da vso deželo, ki jo je obljubil dati tvojim očetom;',
        9: 'če boš ohranjal vse te zapovedi, ki ti jih ta dan zapovedujem, da jih izvršuješ, da ljubiš Gospoda, svojega Boga in da vedno hodiš po njegovih poteh, potem si boš poleg teh treh dodal še tri mesta,',
        10: 'da nedolžna kri ne bo prelita v tvoji deželi, ki ti jo daje v dediščino Gospod, tvoj Bog in bi bila tako na tebi kri.',
        11: 'Toda če katerikoli mož sovraži svojega bližnjega in nanj preži v zasedi in se dvigne zoper njega in ga smrtno udari, da ta umre in pobegne v eno izmed teh mest,',
        12: 'potem bodo starešine njegovega mesta poslali in ga dobili od tam in ga izročili v roko krvnega maščevalca, da bo ta lahko umrl.',
        13: 'Tvoje oko se ga ne bo usmililo, temveč boš iz Izraela odstranil krivdo nedolžne krvi, da bo lahko dobro s teboj.',
        14: 'Ne boš odstranil mejnika svojega bližnjega, ki so ga od starih časov postavili v tvojo dediščino, ki jo boš podedoval v deželi, ki ti jo Gospod, tvoj Bog, daje v last.',
        15: 'Ena priča se ne bo dvignila zoper človeka zaradi katerekoli krivičnosti ali zaradi kateregakoli greha, s katerimkoli grehom je grešil. Zadeva se bo potrdila pri ustih dveh prič ali pri ustih treh prič.',
        16: 'Če kriva priča vstane zoper kateregakoli, da priča zoper njega to, kar je napačno,',
        17: 'potem bosta oba človeka, med katerima je polemika, stala pred Gospodom, pred duhovniki in sodniki, ki bodo v tistih dneh',
        18: 'in sodniki bodo naredili marljivo zasliševanje. Glej, če je priča kriva priča in je lažno pričevala zoper svojega brata,',
        19: 'potem mu boste storili kakor je sam mislil storiti svojemu bratu. Tako boste izmed sebe iztrebili zlo.',
        20: 'Tisti, ki preostanejo, bodo slišali in se bali in odslej med vami ne bodo več zagrešili nobenega takšnega zla.',
        21: 'Tvoje oko se ne bo usmililo, temveč bo življenje šlo za življenje, oko za oko, zob za zob, roka za roko, stopalo za stopalo.',
    },
    20: {
        1: 'Ko greš ven na boj zoper svoje sovražnike in vidiš konje in bojne vozove in ljudstvo, številnejše od tebe, se jih ne boj, kajti Gospod, tvoj Bog, je s teboj, ki te je privedel gor iz egiptovske dežele.',
        2: 'In zgodilo se bo, ko se približate k bitki, da bodo pristopili duhovniki in spregovorili ljudstvu',
        3: 'ter jim rekli: ›Prisluhni, oh Izrael, danes se približujete bitki zoper svoje sovražnike. Naj vaša srca ne slabijo, ne bojte se in ne trepetajte, niti zaradi njih ne bodite prestrašeni,',
        4: 'kajti Gospod, vaš Bog, je ta, ki gre z vami, da se za vas bori zoper vaše sovražnike, da vas reši.‹',
        5: 'Častniki bodo ljudstvu govorili, rekoč: ›Kateri mož je tam, ki je zgradil novo hišo in je ni posvetil? Naj ta gre in se vrne k svoji hiši, da v bitki ne umre in je ne posveti drug moški.',
        6: 'In kateri mož je ta, ki je zasadil vinograd in še ni jedel od njega? Tudi ta naj gre in se vrne k svoji hiši, da v bitki ne umre in drug moški ne jé od njega.',
        7: 'In kateri mož je tam, ki je zaročil ženo in je še ni vzel? Naj gre in se vrne k svoji hiši, da v bitki ne umre in je ne vzame drug moški.‹',
        8: 'Častniki bodo naprej govorili ljudstvu in bodo rekli: ›Kateri moški je tam, ki je bojazljiv in boječ? Naj gre in se vrne k svoji hiši, da ne bo srce njegovih bratov oslabelo tako kakor njegovo srce.‹',
        9: 'Zgodilo se bo, ko bodo častniki končali govorjenje ljudstvu, da bodo postavili poveljnike vojsk, da vodijo ljudstvo.',
        10: 'Ko prideš blizu mesta, da se boriš zoper njega, potem mu razglasi mir.',
        11: 'Zgodilo se bo, če ti ta naredi odgovor miru in ti odpre, potem se bo zgodilo, da ti bodo vsi ljudje, ki so najdeni notri, postali davkoplačevalci in ti bodo služili.',
        12: 'Če pa s teboj ne bo sklenilo miru, temveč se bo zoper tebe vojskovalo, potem ga boš oblegal',
        13: 'in ko ga Gospod, tvoj Bog, izroči v tvoje roke, boš vsakega tamkajšnjega moškega udaril z ostrino meča.',
        14: 'Toda ženske, malčke, živino in vse, kar je v mestu, torej ves njegov plen, boš vzel k sebi in jedel boš plen svojih sovražnikov, ki ti ga je dal Gospod, tvoj Bog.',
        15: 'Tako boš storil vsem mestom, ki so zelo daleč od tebe, ki niso od mest teh narodov.',
        16: 'Toda od mest teh ljudstev, ki ti jih Gospod, tvoj Bog, da za dediščino, ne boš ohranil živega ničesar, kar diha,',
        17: 'temveč jih boš popolnoma uničil, namreč Hetejce, Amoréjce, Kánaance, Perizéjce, Hivéjce in Jebusejce, kakor ti je zapovedal Gospod, tvoj Bog,',
        18: 'da te ne naučijo delati po vseh svojih ogabnostih, ki so jih storili svojim bogovom. Tako bi grešili zoper Gospoda, svojega Boga.',
        19: 'Ko boš dolgo časa oblegal mesto in se vojskoval zoper njega, da ga zavzameš, ne boš uničil njegovih dreves s tem, da bi nadnje privedel sekiro, kajti od njih lahko ješ in ne boš jih posekal, da bi jih uporabil pri obleganju (kajti poljsko drevo je življenje človeku).',
        20: 'Uničil in posekal boš le drevesa, za katera veš, da niso drevesa za hrano. Zoper mesto, ki se bojuje s teboj, boš zgradil branike, dokler ne bo podjarmljeno.',
    },
    21: {
        1: 'Če je nekdo najden ubit na polju, ki ti ga Gospod, tvoj Bog, daje v last, ležeč na polju in se ne ve kdo ga je umoril,',
        2: 'potem bodo prišli tvoje starešine in tvoji sodniki in bodo izmerili [razdaljo] do mest, ki so naokoli tega, ki je umorjen.',
        3: 'Zgodilo se bo, da mesto, ki je bliže umorjenemu človeku, celo starešine tega mesta bodo vzeli telico, s katero še niso delali in ki še ni vlekla jarma,',
        4: 'in starešine tega mesta bodo telico privedli dol v valovito dolino, ki ni niti obdelana niti posejana in tam, v dolini, bodo telici zlomili vrat',
        5: 'in duhovniki, sinovi Lévijevcev, se bodo približali, kajti njih je Gospod, tvoj Bog, izbral, da mu služijo in da blagoslavljajo v Gospodovem imenu, in po njihovi besedi bo vsaka polemika in vsak udarec preizkušen',
        6: 'in vse starešine tega mesta, ki je bliže umorjenemu človeku, si bodo roke umili nad telico, ki je obglavljena v dolini',
        7: 'in odgovorili bodo ter rekli: ›Naše roke niso prelile te krvi niti naše oči tega niso videle.',
        8: 'Bodi usmiljen, oh Gospod, svojemu ljudstvu Izraelu, ki si ga odkupil in ne polagaj nedolžne krvi na svoje ljudstvo Izrael, ki je najbliže.‹ In kri jim bo odpuščena.',
        9: 'Tako boš izmed sebe odvzel krivdo nedolžne krvi, ko boš storil to, kar je pravilno v Gospodovih očeh.',
        10: 'Ko greš naprej v vojno zoper svoje sovražnike in ti jih Gospod, tvoj Bog, izroči v tvoje roke in si jih zajel kot ujetnike',
        11: 'in vidiš med ujetniki lepo žensko in imaš do nje poželenje, da bi jo imel za svojo ženo,',
        12: 'potem jo boš privedel domov, v svojo hišo. Ona si bo obrila svojo glavo in postrigla svoje nohte',
        13: 'in iz sebe bo odložila oblačila svojega ujetništva in ostala bo v tvoji hiši in cel mesec bo objokovala svojega očeta in svojo mater. Potem boš šel noter k njej in boš njen soprog in ona bo tvoja žena.',
        14: 'In zgodilo se bo, če z njo ne boš imel veselja, potem jo boš pustil oditi kamor ona hoče. Toda, ker si jo ponižal, je nikakor ne boš prodal za denar, iz nje ne boš naredil trgovskega blaga.',
        15: 'Če ima mož dve ženi, eno ljubljeno in drugo osovraženo in sta mu rodili otroke, obe, ljubljena in osovražena in če je prvorojenec od tiste, ki je bila osovražena,',
        16: 'potem se bo zgodilo, ko daje svojim sinovom podedovati to, kar ima, da ne sme narediti sina ljubljene prvorojenca pred sinom osovražene, ki je zares prvorojenec,',
        17: 'temveč bo sina osovražene priznal za prvorojenca s tem, da mu da dvojni delež od vsega, kar ima, kajti on je začetek njegove moči; pravica prvorojenca je njegova.',
        18: 'Če ima človek trmoglavega in upornega sina, ki noče ubogati glasu svojega očeta ali glasu svoje matere in ko sta ga karala, da ju noče poslušati,',
        19: 'potem naj ga njegov oče in njegova mati primeta in ga privedeta k starešinam njegovega mesta in k velikim vratom njegovega kraja',
        20: 'in starešinam mesta bosta rekla: ›Ta najin sin je trmoglav in uporen, noče ubogati najinega glasu. Požeruh je in pijanec.‹',
        21: 'In vsi ljudje iz njegovega mesta ga bodo kamnali s kamni, da ta umre. Tako boš zlo odstranil proč izmed vas in ves Izrael bo slišal in se bal.',
        22: 'Če je moški zagrešil greh, vreden smrti, in bo usmrčen in ga obesiš na drevo,',
        23: 'naj njegovo truplo ne ostane vso noč na drevesu, temveč ga boš vsekakor tisti dan pokopal (kajti ta, ki je obešen, je preklet od Boga), da tvoja dežela, ki ti jo Gospod, tvoj Bog, daje za dediščino, ne bo omadeževana.',
    },
    22: {
        1: 'Vola svojega brata ali njegovo ovco ne boš gledal zaiti in se skril pred njimi. V vsakem primeru jih boš ponovno privedel k svojemu bratu.',
        2: 'Če tvoj brat ni blizu tebe ali če ga ne poznaš, potem jo boš privedel v svojo lastno hišo in ta bo s teboj, dokler je tvoj brat ne gre iskat in mu jo boš ponovno vrnil.',
        3: 'Na podoben način boš storil z njegovim oslom in tako boš storil z njegovim oblačilom in z vsemi izgubljenimi stvarmi svojega brata, ki jih je izgubil in si jih našel, boš podobno storil. Ne smeš se skriti.',
        4: 'Osla svojega brata ali njegovega vola ne boš gledal pasti dol ob poti in se skril pred njima. Zagotovo mu boš pomagal, da jih ponovno dvigne.',
        5: 'Ženska ne bo nosila tega, kar pripada moškemu niti moški ne bo oblekel ženskega oblačila, kajti vsi, ki tako delajo, so ogabnost Gospodu, tvojemu Bogu.',
        6: 'Če se ptičje gnezdo znajde pred teboj na poti, na kateremkoli drevesu ali na tleh, bodisi so mladiči ali jajca in mati sedi na mladičih ali na jajcih, ne boš vzel samice z mladiči,',
        7: 'temveč boš vsekakor pustil mater oditi in k sebi vzel mlade, da bo lahko dobro s teboj in da lahko podaljšaš svoje dni.',
        8: 'Ko gradiš novo hišo, potem boš naredil obzidek za svojo streho, da nad svojo hišo ne privedeš krvi, če katerikoli mož pade od tam.',
        9: '§ Svojega vinograda ne boš sejal z različnimi semeni, da ne bi bil sad tvojega semena, ki si ga posejal in sad vinograda omadeževan.',
        10: 'Ne boš oral z volom in oslom skupaj.',
        11: 'Ne boš nosil obleke različnih vrst, kakor iz volne in lanu, skupaj.',
        12: 'Sebi boš naredil rese na štirih četrtinah svoje suknje, s katero se pokrivaš.',
        13: 'Če katerikoli moški vzame ženo in gre noter k njej in jo zasovraži',
        14: 'in da priložnost za opravljanje zoper njo in nadnjo privede zlo ime ter reče: ›Vzel sem to žensko in ko sem prišel k njej, je nisem našel device,‹',
        15: 'potem bosta oče gospodične in njena mati vzela in k starešinam v mestnih velikih vratih prinesla znamenja devištva gospodične',
        16: 'in oče gospodične bo starešinam rekel: ›Svojo hčer sem dal temu možu za ženo, ta pa jo sovraži',
        17: 'in glejte, dal je priložnosti za opravljanje zoper njo, rekoč: ›Tvoje hčere nisem našel device.‹ Vendar so to znamenja devištva moje hčere.‹ In obleko bosta razgrnila pred starešinami mesta.',
        18: 'In starešine tega mesta bodo vzele tega moškega in ga kaznovale',
        19: 'in kaznovali ga bodo s sto šekli srebra in jih dali očetu gospodične, ker je nad Izraelovo devico privedel zlo ime in ona bo njegova žena vse svoje dni. Ne sme je odsloviti.',
        20: 'Toda če je ta stvar resnična in simboli devištva za gospodično niso bili najdeni,',
        21: 'potem bo gospodično privedel ven k vratom hiše njenega očeta in ljudje iz njenega mesta jo bodo kamnali s kamni, da ta umre. Ker je storila neumnost v Izraelu, da igra vlačugo v hiši svojega očeta. Tako boš izmed vas odstranil zlo.',
        22: 'Če je moški najden, da leži z žensko, poročeno s soprogom, potem bosta oba umrla, oba, tako moški, ki je ležal z žensko, in ženska. Tako boš zlo odstranil iz Izraela.',
        23: 'Če je gospodična, ki je devica, zaročena k soprogu in jo moški najde v mestu in leži z njo,',
        24: 'potem boš oba privedel ven, k velikim vratom tega mesta in kamnali ju boste s kamenjem, da umreta. Gospodično, ker ni kričala, kljub temu, da je bila v mestu in moškega, ker je ponižal ženo svojega bližnjega. Tako boš izmed sebe odstranil zlo.',
        25: 'Toda če moški najde zaročeno gospodično na polju in jo moški prisili in leži z njo, potem naj umre samo moški, ki je ležal z njo.',
        26: 'Toda gospodični ne boš ničesar storil. Tam, na gospodični, ni nobenega greha, vrednega smrti, kajti kakor ko se moški vzdiguje zoper svojega bližnjega in ga ubije, celo takšna je ta zadeva,',
        27: 'kajti našel jo je na polju in zaročena gospodična je vpila, pa ni bilo nikogar, da jo reši.',
        28: 'Če moški najde gospodično, ki je devica, ki ni zaročena in jo prime in leži z njo in ju najdejo,',
        29: 'tedaj naj moški, ki je ležal z njo, očetu od gospodične izroči petdeset šeklov srebra in ona bo njegova žena; ker jo je ponižal, je vse svoje dni ne sme odsloviti.',
        30: 'Mož ne bo vzel žene svojega očeta niti odkril krajca očetovega oblačila.',
    },
    23: {
        1: 'Kdor je ranjen v modih ali ima odrezan ud, ne bo vstopil v Gospodovo skupnost.',
        2: 'Mešanec ne bo vstopil v Gospodovo skupnost. Celo do njegovega desetega rodu ne bo vstopil v Gospodovo skupnost.',
        3: 'Amónec ali Moábec ne bosta vstopila v Gospodovo skupnost. Celo do njunega desetega rodu ne bosta vstopila v Gospodovo skupnost na veke,',
        4: 'ker vas niso srečali s kruhom in vodo na poti, ko ste izšli iz Egipta in ker so zoper tebe najeli Beórjevega sina Bileáma iz Petórja v Mezopotamiji, da te prekolne.',
        5: 'Kljub temu Gospod, tvoj Bog, ni hotel prisluhniti Bileámu, temveč ti je Gospod, tvoj Bog, prekletstvo obrnil na blagoslov, ker te je Gospod, tvoj Bog, ljubil.',
        6: 'Vse svoje dni na veke ne boš iskal njihovega miru niti njihovega uspevanja.',
        7: 'Ne boš preziral Edómca, kajti on je tvoj brat. Ne boš preziral Egipčana, kajti tujec si bil v njegovi deželi.',
        8: 'Otroci, ki so rojeni od njih, bodo v Gospodovo skupnost vstopili v svojem tretjem rodu.',
        9: 'Ko gre vojska naprej, zoper tvoje sovražnike, potem se varuj pred vsako zlobno stvarjo.',
        10: 'Če je med vami kakršenkoli moški, ki ni čist zaradi razloga nečistosti, ki se mu pripeti ponoči, potem se bo ločil ven iz tabora, ne bo prišel znotraj tabora.',
        11: 'Temveč bo tako, ko prihaja večer, da se bo umil z vodo, in ko sonce zaide, bo ponovno prišel v tabor.',
        12: 'Imel boš tudi kraj zunaj tabora, kamor boš šel, da se oddvojiš.',
        13: 'Na svojem orožju boš imel lopatico in zgodilo se bo, ko se boš zunaj olajšal, boš s tem kopal in se obrnil nazaj in pokril to, kar pride od tebe,',
        14: 'kajti Gospod, tvoj Bog, hodi v sredi tvojega tabora, da te reši in da pred teboj izroči tvoje sovražnike. Zato bo tvoj tabor svet, da on v tebi ne vidi nobene nečiste stvari in se ne odvrne od tebe.',
        15: 'Služabnika, ki je pred svojim gospodarjem pobegnil k tebi, ne boš izročil njegovemu gospodarju.',
        16: 'Prebival bo s teboj, torej med vami, na tistem kraju, ki ga bo izbral, v enih izmed tvojih velikih vrat, kjer mu je najbolj všeč. Ne boš ga zatiral.',
        17: 'Tam ne bo nobene vlačuge izmed Izraelovih hčera niti posvečenega vlačugarja med Izraelovimi sinovi.',
        18: 'Ne boš prinesel najemnine vlačuge ali pasjega plačila v hišo Gospoda, svojega Boga, za kakršnokoli prisego, kajti celo oboje je ogabnost Gospodu, tvojemu Bogu.',
        19: 'Svojemu bratu ne boš posojal za obresti; obresti od denarja, obresti od živeža, obresti od katerekoli stvari, ki je posojena za obresti.',
        20: 'Tujcu lahko posodiš za obresti, toda svojemu bratu ne boš posojal za obresti, da te Gospod, tvoj Bog, lahko blagoslovi v vsem, česar se loti tvoja roka v deželi, kamor greš, da jo vzameš v last.',
        21: 'Ko boš zaobljubil zaobljubo Gospodu, svojemu Bogu, se ne boš obiral, da to plačaš, kajti Gospod, tvoj Bog, bo to zagotovo zahteval od tebe in to bi bil greh v tebi.',
        22: 'Toda če opustiš, da se zaobljubiš, potem v tebi ne bo greha.',
        23: 'To, kar je odšlo iz tvojih ustnic, boš ohranjal in izvêdel, celó prostovoljno daritev, glede na to, kot si zaobljubil Gospodu, svojemu Bogu, kar si zaobljubil s svojimi usti.',
        24: 'Ko prideš v vinograd svojega bližnjega, potem lahko na svojo lastno željo do sitega ješ grozdje, toda nobenega ne boš položil v svojo posodo.',
        25: 'Ko prideš v stoječe žito svojega bližnjega, potem lahko s svojo roko trgaš klasje, toda s srpom ne boš zamahnil v stoječe žito svojega bližnjega.',
    },
    24: {
        1: 'Kadar si moški vzame ženo in jo poroči in se pripeti, da ona ne najde naklonjenosti v njegovih očeh, ker je v njej našel nekaj nečistega, potem naj ji napiše ločitveni list in ji ga da v roko in jo pošlje ven iz svoje hiše.',
        2: 'Ko je odšla iz njegove hiše, lahko gre in postane žena drugega moškega.',
        3: 'Če jo zadnji mož sovraži in ji napiše ločitveni list in ji ga da v roko in jo pošlje ven iz svoje hiše, ali če zadnji soprog, ki jo je vzel, da bi bila njegova žena, umre,',
        4: 'je njen prejšnji soprog, ki jo je poslal proč, ne sme ponovno vzeti, da bi bila njegova žena, potem ko je omadeževana, kajti to je ogabnost pred Gospodom in ti deželi, ki ti jo daje Gospod, tvoj Bog, za dediščino, ne boš povzročil, da greši.',
        5: 'Ko si je mož vzel novo ženo, ne bo šel ven na vojno niti ne bo obremenjen s kakršnimkoli poslom, temveč bo eno leto doma svoboden in bo razveseljeval svojo ženo, ki jo je vzel.',
        6: 'Noben človek ne bo za jamstvo vzel spodnji ali zgornji mlinski kamen, kajti za jamstvo jemlje človeško življenje.',
        7: 'Če je mož najden, da krade kateregakoli izmed svojih bratov, Izraelovih otrok in iz njega dela trgovsko blago ali ga proda, potem bo ta tat umrl, in ti boš izmed vas iztrebil zlo.',
        8: 'Pazi na nadlogo gobavosti, da marljivo obeležuješ in delaš glede na vse, kar te bodo Lévijevci učili. Kakor sem jim zapovedal tako boste vi obeleževali, da delate.',
        9: 'Spominjaj se, kaj je Gospod, tvoj Bog, storil Mirjam na poti potem, ko ste izšli iz Egipta.',
        10: 'Kadar karkoli posodiš svojemu bratu, ne boš šel v njegovo hišo, da bi dobil svoje jamstvo.',
        11: 'Stal boš zunaj in mož, ki si mu posodil, bo jamstvo prinesel ven k tebi.',
        12: 'Če je mož reven, ne boš spal z njegovim jamstvom.',
        13: 'V vsakem primeru mu boš ponovno izročil jamstvo, ko sonce zaide, da bo lahko spal v svojem lastnem oblačilu in te blagoslovil in to ti bo pravičnost pred Gospodom, tvojim Bogom.',
        14: 'Ne boš zatiral najetega služabnika, ki je reven in pomoči potreben, bodisi je od tvojih bratov ali od tvojih tujcev, ki so v tvoji deželi, znotraj tvojih velikih vrat.',
        15: 'Na njegov dan mu boš dal njegovo najemnino niti ne bo sonce zašlo nad le-to, kajti on je reven in nanjo naravnava svoje srce, da ne bi zoper tebe klical h Gospodu in bi bil tebi to greh.',
        16: 'Očetje ne bodo usmrčeni zaradi otrok niti ne bodo otroci usmrčeni zaradi očetov. Vsak mož bo usmrčen za svoj greh.',
        17: 'Ne boš izkrivljal sodbe tujcu niti siroti niti za jamstvo ne jemlji vdovinega oblačila,',
        18: 'temveč se boš spominjal, da si bil suženj v Egiptu in Gospod, tvoj Bog, te je odkupil od tam. Zato ti zapovedujem, da to stvar storiš.',
        19: 'Ko na svojem polju požanješ svojo žetev in si snop pozabil na polju, ne boš ponovno šel, da ga vzameš. Ta bo za tujca, siroto in vdovo, da te Gospod, tvoj Bog, lahko blagoslovi pri vsem delu tvojih rok.',
        20: 'Kadar klatiš svojo oljko, ne boš ponovno šel preko vej. To bo za tujca, siroto in vdovo.',
        21: 'Kadar nabiraš grozdje iz svojega vinograda, ne boš kasneje paberkoval. To bo za tujca, siroto in vdovo.',
        22: 'Spominjal se boš, da si bil suženj v egiptovski deželi, zato ti zapovedujem, da to stvar storiš.',
    },
    25: {
        1: 'Če je polemika med ljudmi in pridejo na sodbo, da bi jim sodniki lahko sodili, potem bodo opravičili pravičnega in obsodili zlobnega.',
        2: 'Zgodilo se bo, če bo zloben človek vreden, da bi bil pretepen, da mu bo sodnik povzročil, da se uleže in da bo z določenim številom udarcev pretepen pred njegovim obrazom, glede na njegovo krivdo.',
        3: 'Štirideset udarcev mu lahko naloži in ne več, da se ti tvoj brat ne bi zdel onečaščen, če bi prekoračil in ga pretepel z mnogimi udarci nad temi.',
        4: 'Ne boš zavezal gobca volu, kadar mane žito.',
        5: 'Če bratje prebivajo skupaj in eden izmed njih umre in nima otroka, se žena mrtvega ne bo poročila zunaj, s tujcem. Njen svak bo šel noter k njej in jo vzel k sebi za ženo in ji izpolnil dolžnost soprogovega brata.',
        6: 'Zgodilo se bo, da bo prvorojenec, ki ga ona rodi, nasledil ime njegovega brata, ki je mrtev, da njegovo ime ne bo izbrisano iz Izraela.',
        7: 'Če pa mož ne mara vzeti svakinje, potem naj gre žena njegovega brata gor k velikim vratom do starešin in reče: ›Brat mojega soproga odklanja, da bi svojemu bratu vzdignil ime v Izraelu; noče izpolniti dolžnosti brata mojega soproga.‹',
        8: 'Potem ga bodo starešine njegovega mesta poklicali in mu govorili. Če pa se temu zoperstavi in reče: ›Ne maram je vzeti,‹',
        9: 'potem bo žena njegovega brata prišla k njemu v prisotnosti starešin in sezula njegov čevelj iz njegovega stopala in pljunila v njegov obraz in odgovorila ter rekla: ›Tako bo storjeno tistemu možu, ki noče graditi hiše svojega brata.‹',
        10: 'Njegovo ime bo v Izraelu imenovano: ›Hiša tistega, ki je sezut.‹',
        11: 'Kadar se možje skupaj prepirajo drug z drugim in se žena enega približa, da bi svojega soproga osvobodila iz roke tistega, ki ga udarja in iztegne svojo roko, da ga zgrabi za njegove genitalije,',
        12: 'potem boš odsekal njeno roko, tvoje oko se je ne bo usmililo.',
        13: 'V svoji torbi ne boš imel različnih uteži, velike in male.',
        14: 'V svoji hiši ne boš imel različnih mer, velike in male.',
        15: 'Temveč boš imel popolno in pravično utež, popolno in pravično mero boš imel, da bodo tvoji dnevi lahko podaljšani v deželi, ki ti jo daje Gospod, tvoj Bog.',
        16: 'Kajti vsi, ki počno takšne stvari, in vsi, ki počno nepravično, so ogabnost Gospodu, tvojemu Bogu.',
        17: 'Spomni se kaj ti je po poti storil Amálek, ko ste izšli iz Egipta,',
        18: 'kako te je srečal po poti in udaril najbolj zadnje od tebe, torej vse, kar je bilo slabotno za teboj, ko si bil ti slaboten in utrujen, on pa se ni bal Boga.',
        19: 'Zato bo, ko ti bo Gospod, tvoj Bog, dal počitek pred vsemi tvojimi sovražniki naokoli, v deželi, ki ti jo daje Gospod, tvoj Bog, za dediščino, da jo vzameš v last, da boš izpod neba izbrisal spomin na Amáleka. Tega ne boš pozabil.',
    },
    26: {
        1: 'Zgodilo se bo, ko prideš v deželo, ki ti jo v dediščino daje Gospod, tvoj Bog, in jo vzameš v last in v njej prebivaš,',
        2: 'da boš vzel od prvega izmed vseh sadov zemlje, ki jih boš prinesel iz svoje dežele, ki ti jo daje Gospod, tvoj Bog in boš to položil v košaro in boš šel na kraj, ki ga bo izbral Gospod, tvoj Bog, da tam postavi svoje ime.',
        3: 'Šel boš k duhovniku, ki bo v tistih dneh ter mu rekel: ›Ta dan izpovedujem Gospodu, tvojemu Bogu, da sem prišel v deželo, ki jo je Gospod prisegel našim očetom, da nam jo da.‹',
        4: 'Duhovnik bo iz tvoje roke vzel košaro in jo postavil dol pred oltar Gospoda, tvojega Boga.',
        5: 'Govoril boš in pred Gospodom, svojim Bogom, rekel: ›Moj oče je bil Sirec, pripravljen, da umre in odšel je dol v Egipt in tam začasno prebival s peščico in tam postal narod, velik, mogočen in gosto naseljen,',
        6: 'Egipčani pa so z nami postopali zlobno in nas prizadeli in na nas položili trdo suženjstvo.',
        7: 'Ko smo klicali h Gospodu, Bogu svojih očetov, je Gospod slišal naš glas in pogledal na našo stisko in naš trud in naše zatiranje',
        8: 'in Gospod nas je iz Egipta izpeljal z mogočno roko, z iztegnjenim laktom, z veliko strahoto, z znamenji in čudeži',
        9: 'in nas privedel na ta kraj in nam dal to deželo, celó deželo, kjer tečeta mleko in med.',
        10: 'Sedaj glej, prinesel sem prve sadove dežele, ki si jo ti, oh Gospod, dal meni.‹ To boš postavil pred Gospoda, svojega Boga in oboževal boš pred Gospodom, svojim Bogom',
        11: 'in veselil se boš v vsaki dobri stvari, ki jo je Gospod, tvoj Bog, dal tebi in tvoji hiši, ti in Lévijevec in tujec, ki je med vami.',
        12: 'Ko si končal desetinjenje vseh desetin svojega narasta v tretjem letu, ki je leto desetinjenja in si to dal Lévijevcu, tujcu, siroti in vdovi, da lahko jedo znotraj tvojih velikih vrat in so nasičeni,',
        13: 'potem boš rekel pred Gospodom, svojim Bogom: ›Odnesel sem posvečene stvari iz svoje hiše in jih prav tako izročil Lévijevcu, tujcu, siroti in vdovi, glede na vse tvoje zapovedi, ki si mi jih zapovedal. Nisem prekršil tvojih zapovedi niti jih nisem pozabil.',
        14: 'V svojem žalovanju nisem jedel od tega, niti nisem vzel proč česarkoli za kakršnokoli nečisto uporabo, niti nisem dal karkoli od tega za mrtvega, temveč sem prisluhnil glasu Gospoda, svojega Boga in storil glede na vse, kar si mi zapovedal.',
        15: 'Poglej navzdol iz svojega svetega prebivališča, iz nebes in blagoslovi svoje ljudstvo Izrael in deželo, ki si nam jo dal, kakor si prisegel našim očetom, deželo, kjer tečeta mleko in med.‹',
        16: 'Ta dan ti je Gospod, tvoj Bog, zapovedal, da izpolnjuješ te zakone in sodbe. Ti jih boš torej ohranjal in izvrševal z vsem svojim srcem in z vso svojo dušo.',
        17: 'Ta dan si govoril Gospodu, da bi bil tvoj Bog in da bi hodil po njegovih poteh, ohranjal njegove zakone, njegove zapovedi, njegove sodbe in da bi prisluhnil njegovemu glasu',
        18: 'in Gospod ti je ta dan odgovoril, da bi bil njegovo izvoljeno ljudstvo, kakor ti je obljubil in da bi varoval vse njegove zapovedi',
        19: 'in da bi te naredil višjega nad vsemi narodi, ki jih je naredil, v hvali, v imenu, v časti in da bi bil lahko sveto ljudstvo Gospodu, svojemu Bogu, kakor je govoril.«',
    },
    27: {
        1: 'Mojzes je z Izraelovimi starešinami ljudstvu zapovedal, rekoč: »Ohranjajte vse zapovedi, ki vam jih ta dan zapovedujem.',
        2: 'In zgodilo se bo na dan, ko boste čez Jordan prečkali v deželo, ki ti jo daje Gospod, tvoj Bog, da si boš postavil velike kamne in jih pobelil z apnom',
        3: 'in nanje boš zapisal vse besede te postave, ko si prečkal, da si lahko vstopil v deželo, ki ti jo daje Gospod, tvoj Bog, deželo, kjer tečeta mleko in med, kakor ti je obljubil Gospod, Bog tvojih očetov.',
        4: 'Zatorej bo, ko boste odšli čez Jordan, da boste postavili te kamne, ki sem vam jih zapovedal ta dan, na gori Ebál in jih pobelili z apnom.',
        5: 'Tam boš zgradil oltar Gospodu, svojemu Bogu, oltar iz kamnov. Nobenega železnega orodja ne boš dvignil nadnje.',
        6: 'Iz celih kamnov boš zgradil oltar Gospodu, svojemu Bogu in na njem boš daroval žgalne daritve Gospodu, svojemu Bogu.',
        7: 'Daroval boš mirovne daritve in tam boš jedel in se veselil pred Gospodom, svojim Bogom.',
        8: 'Na kamne boš zelo jasno napisal vse besede te postave.«',
        9: 'Mojzes in duhovniki, Lévijevci, so vsemu Izraelu spregovorili, rekoč: »Pazi in prisluhni, oh Izrael. Ta dan si postal ljudstvo Gospoda, svojega Boga.',
        10: 'Ubogal boš torej glas Gospoda, svojega Boga in izvrševal njegove zapovedi in njegove zakone, ki ti jih ta dan zapovedujem.«',
        11: 'Mojzes je ta isti dan ljudstvu naročil, rekoč:',
        12: '»Ti bodo stali na gori Garizím, da blagoslovijo ljudstvo, ko pridete čez Jordan: Simeon, Levi, Juda, Isahár, Jožef in Benjamin.',
        13: 'In ti bodo stali na gori Ebál, da preklinjajo: Ruben, Gad, Aser, Zábulon, Dan in Neftáli.',
        14: 'Lévijevci bodo z močnim glasom govorili in rekli vsem Izraelovim možem:',
        15: '›Preklet bodi mož, ki dela kakršnokoli rezano ali ulito podobo, ogabnost Gospodu, delo rok rokodelca in jo postavi na skrit kraj.‹ In vse ljudstvo bo odgovorilo in reklo: ›Amen.‹',
        16: '›Preklet bodi kdor prezira svojega očeta ali svojo mater.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        17: '›Preklet bodi, kdor odstranja mejnik svojega bližnjega.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        18: '›Preklet bodi, kdor slepega pripravi, da zaide iz poti.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        19: '›Preklet bodi, kdor izkrivlja sodbo tujca, sirote in vdove.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        20: '›Preklet bodi, kdor leži z ženo svojega očeta, ker je odkril krajec očetovega oblačila.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        21: '›Preklet bodi, kdor leži s katerokoli vrsto živali.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        22: '›Preklet bodi, kdor leži s svojo sestro, hčerjo svojega očeta ali hčerjo svoje matere.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        23: '›Preklet bodi, kdor leži s svojo taščo.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        24: '›Preklet bodi, kdor na skrivnem udarja svojega bližnjega.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        25: '›Preklet bodi, kdor jemlje nagrado, da ubije nedolžno osebo.‹ In vse ljudstvo bo reklo: ›Amen.‹',
        26: '›Preklet bodi, kdor ne potrjuje vseh besed te postave, da bi jih izpolnjeval.‹ In vse ljudstvo bo reklo: ›Amen.‹«',
    },
    28: {
        1: 'Zgodilo se bo, če boš marljivo prisluhnil glasu Gospoda, svojega Boga, da obeležuješ in da izpolnjuješ vse njegove zapovedi, ki sem ti jih zapovedal ta dan, da te bo Gospod, tvoj Bog, postavil visoko, nad vse narode zemlje',
        2: 'in vsi ti blagoslovi bodo prišli nadte in te dosegli, če boš prisluhnil glasu Gospoda, svojega Boga.',
        3: 'Blagoslovljen boš v mestu in blagoslovljen boš na polju.',
        4: 'Blagoslovljen bo sad tvojega telesa in sad tvojih tal in sad tvoje živine, prireja tvojega goveda in tropov tvojih ovc.',
        5: 'Blagoslovljena bo tvoja košara in tvoja shramba.',
        6: 'Blagoslovljen boš, ko prihajaš in blagoslovljen boš, ko odhajaš.',
        7: 'Gospod bo tvojim sovražnikom, ki se dvignejo zoper tebe, povzročil da bodo udarjeni pred tvojim obrazom. Zoper tebe bodo prišli po eni poti, pred teboj bodo pobegnili po sedmih poteh.',
        8: 'Gospod bo zapovedal blagoslov nad teboj v tvojih skladiščih in vsemu temu, česar se loti tvoja roka, in blagoslovil te bo v deželi, ki ti jo daje Gospod, tvoj Bog.',
        9: 'Gospod te bo utrdil sebi za sveto ljudstvo, kakor ti je prisegel, če boš ohranjal zapovedi Gospoda, svojega Boga in hodil po njegovih poteh.',
        10: 'Vse ljudstvo zemlje bo videlo, da si imenovan po Gospodovem imenu in se te bodo bali.',
        11: 'Gospod te bo storil obilnega v dobrinah, v sadu tvojega telesa in v prireji tvoje živine in v sadu tvojih tal, v deželi, ki jo je Gospod prisegel tvojim očetom, da ti jo da.',
        12: 'Gospod ti bo odprl svojo dobro zakladnico, nebo, da daje dež tvoji deželi v svojem obdobju in da blagoslovi vse delo tvoje roke in posojal boš mnogim narodom, ti pa si ne boš izposojal.',
        13: 'Gospod te bo naredil za glavo in ne za rep. Ti boš samo zgoraj in ne boš spodaj, če boš prisluhnil zapovedim Gospoda, svojega Boga, ki sem ti jih zapovedal ta dan, da jih obeležuješ in izpolnjuješ',
        14: 'in ne boš šel stran od katerekoli izmed besed, ki sem ti jih ta dan zapovedal, ne k desni roki ne k levi, da bi šel za drugimi bogovi, da jim služiš.',
        15: 'Temveč se bo zgodilo, če ne boš prisluhnil glasu Gospoda, svojega Boga, da obeležuješ izvrševati vse njegove zapovedi in njegove zakone, ki sem ti jih ta dan zapovedal, da bodo nadte prišla vsa ta prekletstva in te dohitela.',
        16: 'Preklet boš v mestu in preklet boš na polju.',
        17: 'Preklet bo tvoj koš in tvoja shramba.',
        18: 'Preklet bo sad tvojega telesa in sad tvoje dežele, prirast tvojega goveda in tropov tvojih ovc.',
        19: 'Preklet boš, ko prihajaš in preklet boš, ko odhajaš.',
        20: 'Gospod bo nadte poslal prekletstvo, draženje in grajo v vsem, česar se lotiš s svojo roko, da bi storil, dokler ne boš uničen in dokler hitro ne premineš; zaradi zlobnosti svojih dejanj, s katerimi si me zapustil.',
        21: 'Gospod bo storil, da se te bo trdno oklenila kužna bolezen, dokler te ne použije iz dežele, kamor greš, da jo vzameš v last.',
        22: 'Gospod te bo udaril s sušico, z vročino, z vnetjem in z izjemno vročico, z mečem, s kvarjenjem in s plesnijo; in preganjale te bodo, dokler ne premineš.',
        23: 'Tvoje nebo, ki je nad tvojo glavo, bo bron in zemlja, ki je pod teboj, bo železo.',
        24: 'Gospod bo dež tvoje dežele spremenil v prašek in prah. Z neba bo padal nadte, dokler ne boš uničen.',
        25: 'Gospod ti bo povzročil, da boš udarjen pred svojimi sovražniki. Po eni poti boš šel ven zoper njih in po sedmih poteh boš bežal pred njimi in odstranjen boš v vsa kraljestva zemlje.',
        26: 'Tvoje truplo bo hrana vsej perjadi neba in zemeljskim živalim in noben človek jih ne bo odganjal.',
        27: 'Gospod te bo udaril z egiptovskimi mehurji, s hemoroídi, s krasto in s srbečico, od katerih ne moreš biti ozdravljen.',
        28: 'Gospod te bo udaril z norostjo, slepoto in osuplostjo srca.',
        29: 'Opoldan boš tipal, kakor slepi tipa v temi in ne boš uspeval na svojih poteh in vselej boš samo zatiran in plenjen in noben človek te ne bo rešil.',
        30: 'Zaročil boš žensko, z njo pa bo ležal drug moški. Zgradil boš hišo, pa ne boš prebival v njej. Zasadil boš vinograd, pa ne boš obiral njegovega grozdja.',
        31: 'Tvoj vol bo zaklan pred tvojimi očmi, pa od njega ne boš jedel. Tvoj osel bo nasilno vzet izpred tvojega obraza, pa ne bo povrnjen k tebi. Tvoje ovce bodo dane tvojim sovražnikom in nikogar ne boš imel, da jih reši.',
        32: 'Tvoji sinovi in tvoje hčere bodo izročeni drugemu ljudstvu in tvoje oči bodo gledale in s hrepenenjem ves dan koprnele po njih, pa v tvoji roki ne bo nobene moči.',
        33: 'Sad tvoje dežele in vse tvoje trude bo narod, ki ga ne poznaš, požrl in ti boš vedno samo zatiran in zdrobljen.',
        34: 'Tako da boš besen zaradi prizora svojih oči, ki ga boš videl.',
        35: 'Gospod te bo v kolenih in v nogah udaril z bolečimi mehurji, ki ne morejo biti ozdravljeni, od podplata tvojega stopala do vrha tvoje glave.',
        36: 'Gospod in tvoj kralj, ki si ga boš postavil nadse, te bo privedel k narodu, ki ga nisi poznal niti ti niti tvoji očetje in tam boš služil drugim bogovom, lesu in kamnu.',
        37: 'Postal boš osuplost, pregovor in tarča posmeha med vsemi narodi, kamor te bo vodil Gospod.',
        38: 'Na polje boš nosil obilje semena, zbral pa ga boš le malo, kajti to bo požrla leteča kobilica.',
        39: 'Sadil boš vinograde in jih obrezoval, toda niti ne boš pil od vina, niti nabiral grozdja, kajti ličinke jih bodo pojedle.',
        40: 'Po vseh svojih pokrajinah boš imel oljke, toda sebe ne boš mazilil z oljem, ker bodo tvoje oljke odvrgle svoj sad.',
        41: 'Zaplodil boš sinove in hčere, toda ne boš jih užival, ker bodo šli v ujetništvo.',
        42: 'Vsa tvoja drevesa in sad tvoje dežele bo požrla leteča kobilica.',
        43: 'Tujec, ki je znotraj tebe, se bo zelo visoko povzpel nadte, ti pa se boš spustil zelo nizko.',
        44: 'Posojal ti bo, ti pa njemu ne boš posojal. On bo glava, ti pa rep.',
        45: 'Poleg tega bodo nadte prišla vsa ta prekletstva in te zasledovala in dosegla, dokler ne boš uničen, ker nisi prisluhnil glasu Gospoda, svojega Boga, da ohranjaš njegove zapovedi in njegove zakone, ki ti jih je zapovedal.',
        46: 'Ta bodo na tebi za znamenje in za čudo in nad tvojim semenom na veke.',
        47: 'Ker zaradi obilja vseh stvari nisi služil Gospodu, svojemu Bogu, z radostjo in z veseljem srca,',
        48: 'zato boš služil svojim sovražnikom, ki jih bo Gospod poslal zoper tebe, v lakoti, v žeji, v nagoti in v pomanjkanju vseh stvari in na tvoj vrat bo položil železen jarem, dokler te ne uniči.',
        49: 'Gospod bo zoper tebe od daleč privedel narod, od konca zemlje, tako naglo, kakor leti orel. Narod, katerega jezika ne boš razumel,',
        50: 'narod krutega obličja, ki se ne bo oziral na osebo starca niti mladim izkazoval naklonjenosti.',
        51: 'Jedel bo sad tvoje živine in sad tvoje dežele, dokler ne boš uničen, ki ti tudi ne bo pustil niti žita, vina ali olja ali prirasta tvojega goveda ali tropov tvojih ovc, dokler te ne uniči.',
        52: 'Oblegal te bo v vseh tvojih velikih vratih, dokler se tvoji visoki in mogočni utrjeni zidovi, v katere si zaupal, ne zrušijo po vsej tvoji deželi in oblegal te bo v vseh tvojih velikih vratih, po vsej tvoji deželi, ki ti jo je dal Gospod, tvoj Bog.',
        53: 'Jedel boš sad svojega lastnega telesa, meso svojih sinov in svojih hčera, ki ti jih je dal Gospod, tvoj Bog, ob obleganju in v tesnobi, s katero te bodo stiskali tvoji sovražniki,',
        54: 'tako da bo oko moža, ki je med vami nežen in zelo prefinjen, hudobno proti svojemu bratu in proti ženi svojega naročja in proti preostanku svojih otrok, ki jih bo pustil,',
        55: 'tako da nikomur izmed njih ne bo dal mesa svojih otrok, ki jih bo jedel, ker mu ob obleganju in v tesnobi, s katero te bodo stiskali tvoji sovražniki in vznemirjali v vseh tvojih velikih vratih, ničesar ne bo preostalo.',
        56: 'Oko nežne in prefinjene ženske med vami, ki zaradi prefinjenosti in nežnosti ne bi niti poskusila postaviti podplata svojega stopala na tla, bo hudobno napram soprogu svojega naročja in napram svojemu sinu in napram svoji hčeri',
        57: 'in napram svojemu otročičku, ki pride ven izmed njenih stopal in napram svojim otrokom, ki jih bo nosila, kajti na skrivaj jih bo jedla zaradi pomanjkanja vseh stvari, ob obleganju in tesnobi, s katero te bo tvoj sovražnik stiskal znotraj tvojih velikih vrat.',
        58: 'Če ne boš obeleževal, da storiš vse besede te postave, ki so zapisane v tej knjigi, da bi se lahko bal tega slavnega in strašnega imena, GOSPODA, SVOJEGA BOGA,',
        59: 'tedaj bo Gospod naredil tvoje nadloge in nadloge tvojega semena težke, celó velike nadloge in dolgo trajajoče in boleče bolezni in dolgo trajajoče.',
        60: 'Poleg tega bo nadte privedel vse egiptovske bolezni, ki si se jih bal in te se te bodo trdno držale.',
        61: 'Prav tako vsako bolezen in vsako nadlogo, ki ni zapisana v knjigi te postave, tudi te bo Gospod privedel nadte, dokler ne boš uničen.',
        62: 'Vas pa bo ostalo le malo po številu, medtem ko vas je bilo zaradi množice kakor zvezd neba, ker nisi hotel ubogati glasu Gospoda, svojega Boga.',
        63: 'Zgodilo se bo, da kakor se je Gospod nad vami veselil, da vam stori dobro in vas množi, tako se bo Gospod nad vami veselil, da vas uniči in da vas privede v nič in vi boste izruvani iz dežele, kamor greš, da jo vzameš v last.',
        64: 'Gospod te bo razkropil med vsa ljudstva, od enega konca zemlje, celo do drugega in tam boš služil drugim bogovom, ki jih nisi poznal ne ti ne tvoji očetje, celó lesu in kamnu.',
        65: 'Med tistimi narodi ne boš našel nobenega olajšanja niti podplat tvojega stopala ne bo imel počitka, temveč ti bo tam Gospod dal trepetajoče srce, pešajoče oči in umsko bolest',
        66: 'in tvoje življenje bo pred teboj viselo v dvomu in bal se boš podnevi in ponoči in nobene gotovosti svojega življenja ne boš imel.',
        67: 'Zjutraj boš rekel: »Da bi Bog dal, da bi bil večer!« In zvečer boš rekel: »Da bi Bog dal, da bi bilo jutro!« Zaradi strahu svojega srca, s katerim se boš bal, in zaradi pogleda svojih oči, ki ga boš gledal.',
        68: 'Gospod te bo z ladjami ponovno privedel v Egipt, po poti, o kateri sem ti govoril: »Ne boš je več videl.« Tam boste prodani svojim sovražnikom za sužnje in sužnjice in noben mož vas ne bo kupil.',
    },
    29: {
        1: 'To so besede zaveze, ki jo je Gospod zapovedal Mojzesu, da jo z Izraelovimi otroki sklene v moábski deželi, poleg zaveze, ki jo je z njimi sklenil na Horebu.',
        2: 'Mojzes je klical vsemu Izraelu in jim rekel: »Videli ste vse, kar je Gospod storil pred vašimi očmi v egiptovski deželi faraonu in vsem njegovim služabnikom in vsej njegovi deželi,',
        3: 'velike preizkušnje, ki so jih videle tvoje oči, znamenja in tiste velike čudeže.',
        4: 'Vendar vam Gospod do tega dne ni dal srca, da zaznate, oči, da vidite in ušesa, da slišite.',
        5: 'Jaz sem vas štirideset let vodil po divjini. Vaša oblačila se na vas niso postarala in tvoj čevelj na tvojem stopalu se ni postaral.',
        6: 'Niste jedli kruha niti pili vina ali močne pijače, da bi lahko spoznali, da jaz sem Gospod, vaš Bog.',
        7: 'In ko ste prišli na ta kraj, sta Sihón, kralj v Hešbónu in bašánski kralj Og, prišla ven zoper nas v bitko in mi smo ju udarili.',
        8: 'Zavzeli smo njuno deželo in jo izročili v dediščino Rubenovcem, Gádovcem in polovici Manásejevega rodu.',
        9: 'Varujte torej besede te zaveze in jih izvršujte, da boste lahko uspevali v vsem svojem delu.',
        10: 'Vsi izmed vas ta dan stojite pred Gospodom, vašim Bogom: vaši poveljniki vaših rodov, vaše starešine in vaši častniki, z vsemi Izraelovimi možmi,',
        11: 'vaši malčki, vaše žene in tvoj tujec, ki je v tvojem taboru, od sekalca tvojega lesa, do prinašalca tvoje vode,',
        12: 'da bi vstopil v zavezo z Gospodom, svojim Bogom in v njegovo prisego, ki jo je Gospod, tvoj Bog, ta dan sklenil s teboj,',
        13: 'da bi te ta dan lahko osnoval za svoje ljudstvo in da bi ti bil on lahko Bog, kakor ti je rekel in kakor je prisegel tvojim očetom, Abrahamu, Izaku in Jakobu.',
        14: 'Niti te zaveze in te prisege ne sklepam samo s teboj,',
        15: 'temveč s tistim, ki ta dan stoji tukaj z nami pred Gospodom, svojim Bogom in tudi s tistim, ki ga ta dan ni tukaj z nami',
        16: '(kajti veste, kako smo prebivali v egiptovski deželi in kako smo prišli skozi narode, mimo katerih ste šli',
        17: 'in ste videli njihove ogabnosti in njihove malike, les in kamen, srebro in zlato, ki so bili med njimi)',
        18: 'da ne bi bilo med vami moža ali ženske ali družine ali rodu, katerega srce se ta dan obrača od Gospoda, našega Boga, da gre in služi bogovom teh narodov, da ne bi bilo med vami korenine, ki obrodi žolč in pelin',
        19: 'in zgodi se, ko sliši besede tega prekletstva, da se blagoslovi v svojem srcu, rekoč: ›Imel bom mir, čeprav hodim v zamisli svojega srca, da žeji dodajam pijanost.‹',
        20: 'Gospod mu ne bo prizanesel, temveč se bosta potem Gospodova jeza in njegova ljubosumnost kadili zoper tega človeka in vsa prekletstva, ki so zapisana v tej knjigi, bodo legla nanj in Gospod bo njegovo ime izbrisal izpod neba.',
        21: 'Gospod ga bo izmed vseh Izraelovih rodov oddvojil v zlo, glede na vsa prekletstva zaveze, ki so zapisana v tej knjigi postave,',
        22: 'tako da bodo rekli prihajajočemu rodu tvojih otrok, ki bodo vstali za vami in tujcu, ki bo prišel iz daljne dežele, ko bodo videli nadloge te dežele in bolezni, ki jih je Gospod položil nanjo',
        23: 'in da je njegova celotna dežela žveplo, sol in gorenje, da ta ni posejana niti ne vzbrsti niti nobena trava ne raste na njej, kakor razdejanje Sódome, Gomóre, Adme in Cebojíma, ki jih je Gospod uničil v svoji jezi in v svojem besu.',
        24: 'Celo vsi narodi bodo rekli: ›Zakaj je Gospod tako storil tej deželi? Kaj pomeni gorenje te velike jeze?‹',
        25: 'Potem bodo možje rekli: ›Ker so zapustili zavezo Gospoda, Boga svojih očetov, ki jo je z njimi sklenil, ko jih je privedel ven iz egiptovske dežele,',
        26: 'kajti šli so in služili drugim bogovom in jih oboževali, bogovom, ki jih niso poznali in ki jim jih on ni dal',
        27: 'in Gospodova jeza je bila vžgana zoper to deželo, da nadnjo privede vsa prekletstva, ki so zapisana v tej knjigi.',
        28: 'Gospod jih je v jezi izkoreninil iz njihove dežele, v besu, v velikem ogorčenju in jih vrgel v drugo deželo, kakor je to ta dan.‹',
        29: 'Skrivne stvari pripadajo Gospodu, našemu Bogu, toda tiste stvari, ki so razodete, pripadajo nam in našim otrokom na veke, da lahko storimo vse besede te postave.',
    },
    30: {
        1: 'Zgodilo se bo, ko vse te stvari pridejo nadte, blagoslov in prekletstvo, ki sem ga postavil predte in si jih boš priklical v um med vsemi narodi, kamor te je Gospod, tvoj Bog, pregnal',
        2: 'in se boš vrnil h Gospodu, svojemu Bogu in ubogal njegov glas glede na vse, kar sem ti ta dan zapovedal, tebi in tvojim otrokom, z vsem svojim srcem in z vso svojo dušo,',
        3: 'da bo potem Gospod, tvoj Bog, obrnil tvoje ujetništvo in imel sočutje nad teboj, in te bo vrnil in zbral od vseh narodov, kamor te je Gospod, tvoj Bog, razkropil.',
        4: 'Če bo kdorkoli izmed tvojih izgnan do skrajnih delov neba, te bo od tam zbral Gospod, tvoj Bog in te privedel od tam.',
        5: 'Gospod, tvoj Bog, te bo privedel v deželo, ki so jo tvoji očetje vzeli v last in vzel jo boš v last in storil ti bo dobro in te bolj pomnožil kot tvoje očete.',
        6: 'Gospod, tvoj Bog, bo obrezal tvoje srce in srce tvojega semena, da ljubiš Gospoda, svojega Boga, z vsem svojim srcem in z vso svojo dušo, da boš lahko živel.',
        7: 'Gospod, tvoj Bog, bo vsa ta prekletstva položil na tvoje sovražnike in na tiste, ki te sovražijo, ki so te preganjali.',
        8: 'Vrnil se boš in ubogal Gospodov glas in izpolnjeval vse njegove zapovedi, ki sem ti jih ta dan zapovedal.',
        9: 'In Gospod, tvoj Bog, te bo storil obilnega v vsakem delu tvoje roke, v sadu tvojega telesa, v prireji tvoje živine in v sadu tvoje dežele, tebi v dobro, kajti Gospod se bo, tebi v dobro, ponovno veselil nad teboj, kakor se je veselil nad tvojimi očeti,',
        10: 'če boš prisluhnil glasu Gospoda, svojega Boga, da ohranjaš njegove zapovedi in njegove zakone, ki so zapisani v knjigi te postave in če se obrneš h Gospodu, svojemu Bogu, z vsem svojim srcem in z vso svojo dušo.',
        11: 'Kajti ta zapoved, ki sem ti jo ta dan zapovedal, ta ni skrita pred teboj niti ni daleč proč.',
        12: 'Ta ni v nebesih, da bi lahko rekel: ›Kdo bo za nas šel gor do nebes in jo privede k nam, da bi jo lahko slišali in izpolnjevali?‹',
        13: 'Niti to ni prek morja, da bi lahko rekel: ›Kdo bo za nas šel čez morje in jo privede k nam, da bi jo lahko slišali in izpolnjevali?‹',
        14: 'Temveč je beseda zelo blizu tebe, v tvojih ustih in v tvojem srcu, da jo lahko izpolniš.',
        15: 'Poglej, predte sem ta dan postavil življenje in dobro ter smrt in zlo,',
        16: 'v tem, da sem ti ta dan zapovedal, da ljubiš Gospoda, svojega Boga, da hodiš po njegovih poteh in varuješ njegove zapovedi, njegove zakone in njegove sodbe, da boš lahko živel in se množil in Gospod, tvoj Bog, te bo blagoslovil v deželi, kamor greš, da jo vzameš v last.',
        17: 'Toda če se tvoje srce odvrne, tako da ne boš prisluhnil, temveč boš odveden proč in slavil druge bogove in jim služil,',
        18: 'ti ta dan naznanjam, da se boš zagotovo pogubil in da ne boš podaljšal svojih dni v deželi, kamor greš čez Jordan, da jo vzameš v last.',
        19: 'Danes kličem nebo in zemljo za pričo zoper tebe, da sem predte postavil življenje in smrt, blagoslov in prekletstvo. Zato izberi življenje, da boš lahko živel tako ti kakor tvoje seme,',
        20: 'da lahko ljubiš Gospoda, svojega Boga in da lahko ubogaš njegov glas in da se lahko trdno pridružiš k njemu, kajti on je tvoje življenje in dolžina tvojih dni, da boš lahko prebival v deželi, ki jo je Gospod prisegel tvojim očetom, Abrahamu, Izaku in Jakobu, da jim jo da.«',
    },
    31: {
        1: 'Mojzes je odšel in te besede spregovoril vsemu Izraelu.',
        2: 'Rekel jim je: »Jaz sem ta dan star sto dvajset let. Ne morem več hoditi ven in vstopati noter. Tudi Gospod mi je rekel: ›Ti ne boš šel preko tega Jordana.‹',
        3: 'Gospod, tvoj Bog, bo šel preko pred teboj in on bo izpred tebe uničil te narode in ti jih boš vzel v last in Józue, on bo šel preko pred teboj, kakor je rekel Gospod.',
        4: 'Gospod jim bo storil kakor je storil Sihónu in Ogu, kraljema Amoréjcev in njuni deželi, ki ju je uničil.',
        5: 'Gospod ju bo izročil pred tvoj obraz, da jima boš lahko storil glede na vse zapovedi, ki sem ti jih zapovedal.',
        6: 'Bodi močan in odločnega poguma, ne boj se niti se jih ne plaši, kajti Gospod, tvoj Bog, on je ta, ki gre s teboj; ne bo te razočaral niti te ne bo zapustil.«',
        7: 'Mojzes je zaklical k Józuetu in mu pred očmi vsega Izraela rekel: »Bodi močan in odločnega poguma, kajti s tem ljudstvom moraš iti v deželo, ki jo je Gospod prisegel njihovim očetom, da jim jo da; in ti jim boš povzročil, da jo podedujejo.',
        8: 'Gospod, on je ta, ki gre pred teboj. S teboj bo, ne bo te razočaral niti te ne bo zapustil. Ne boj se niti ne bodi zaprepaden.«',
        9: 'Mojzes je zapisal to postavo in jo izročil duhovnikom, sinovom Lévijevcev, ki so nosili skrinjo Gospodove zaveze, in vsem Izraelovim starešinam.',
        10: 'Mojzes jim je zapovedal, rekoč: »Ob koncu vsakih sedmih let, na slovesno leto odpusta, na šotorski praznik,',
        11: 'ko pride ves Izrael, da se prikaže pred Gospodom, tvojim Bogom, na kraju, ki ga bo on izbral, boš to postavo bral pred vsem Izraelom v njihovo uho.',
        12: 'Skupaj zberi ljudstvo, može, žene, otroke in svojega tujca, ki je znotraj tvojih velikih vratih, da lahko slišijo in da se lahko naučijo in se bojijo Gospoda, svojega Boga in obeležujejo, da storijo vse besede te postave',
        13: 'in da njihovi otroci, ki niso poznali ničesar, lahko slišijo in se naučijo bati se Gospoda, svojega Boga, tako dolgo kot vi živite v deželi, kamor greste prek Jordana, da jo vzamete v last.«',
        14: 'Gospod je rekel Mojzesu: »Glej, približujejo se tvoji dnevi, ko moraš umreti. Pokliči Józueta in se postavita v šotorskem svetišču skupnosti, da mu lahko dam naročilo.« Mojzes in Józue sta odšla in se postavila v šotorskem svetišču skupnosti.',
        15: 'Gospod se je prikazal v šotorskem svetišču, v oblačnem stebru in oblačni steber je stal nad vrati šotorskega svetišča.',
        16: 'Gospod je rekel Mojzesu: »Glej, zaspal boš s svojimi očeti in to ljudstvo se bo vzdignilo in se šlo vlačugat za bogovi tujcev dežele, v katero gredo, da bi bili med njimi in zapustili me bodo in prelomili mojo zavezo, ki sem jo sklenil z njimi.',
        17: 'Potem bo na tisti dan moja jeza vneta zoper njih in zapustil jih bom in svoj obraz bom skril pred njimi in použiti bodo in številna zla in težave jih bodo zadele, tako da bodo na tisti dan rekli: ›Ali niso nad nas prišla ta zla, ker med nami ni našega Boga?‹',
        18: 'Na tisti dan bom zagotovo skril svoj obraz zaradi vseh hudobij, ki jih bodo naredili v tem, da so se obrnili k drugim bogovom.',
        19: 'Zdaj si torej zapišite to pesem in jo učite Izraelove otroke. Položite jo v njihova usta, da bo ta pesem lahko priča zame zoper Izraelove otroke.',
        20: 'Kajti ko jih bom privedel v deželo, ki sem jo prisegel njihovim očetom, kjer tečeta mleko in med in bodo jedli in se nasitili in postali debeli, potem se bodo obrnili k drugim bogovom in jim služili in me izzivali in prelomili mojo zavezo.',
        21: 'Zgodilo se bo, ko jih bodo doletela mnoga zla in stiske, da bo ta pesem pričala zoper njih kakor priča, kajti ta ne bo pozabljena iz ust njihovega semena, kajti jaz poznam njihove zamisli, s katerimi hodijo naokoli, celo sedaj, preden sem jih privedel v deželo, ki sem jim jo prisegel.«',
        22: 'Zato je Mojzes isti dan napisal to pesem in jo učil Izraelove otroke.',
        23: 'Nunovemu sinu Józuetu je dal zadolžitev in rekel: »Bodi močan in odločnega poguma, kajti ti boš Izraelove otroke privedel v deželo, ki sem jim jo prisegel in jaz bom s teboj.«',
        24: 'Pripetilo se je, ko je Mojzes končal s pisanjem besed te postave v knjigo, dokler niso bile dokončane,',
        25: 'da je Mojzes zapovedal Lévijevcem, ki so nosili skrinjo Gospodove zaveze, rekoč:',
        26: '»Vzemite to knjigo postave in jo postavite v stran skrinje zaveze Gospoda, svojega Boga, da bo ta lahko tam za pričo zoper tebe.',
        27: 'Kajti poznam tvoj upor in tvoj trdi vrat. Glej, medtem ko sem z vami ta dan še živ, ste bili uporni zoper Gospoda in koliko bolj po moji smrti?',
        28: 'Zberite k meni vse starešine svojih rodov in svoje častnike, da lahko te besede govorim v njihova ušesa in kličem nebo in zemljo, da pričata zoper njih.',
        29: 'Kajti vem, da se boste po moji smrti popolnoma izpridili in odvrnili od poti, ki sem vam jo zapovedal in zlo vas bo zadelo v zadnjih dneh, ker boste počeli zlo v Gospodovih očeh, da ga dražite k jezi skozi dela svojih rok.«',
        30: 'Mojzes je na ušesa vse Izraelove skupnosti govoril besede te pesmi, dokler se niso končale.',
    },
    32: {
        1: '»Pazljivo prisluhni, oh ti nebo, jaz pa bom govoril in sliši, oh zemlja, besede mojih ust.',
        2: 'Moj nauk bo kapljal kakor dež, moj govor bo rosil kakor rosa, kakor dežek na nežno zelišče in kakor nalivi na travo,',
        3: 'ker bom razglašal Gospodovo ime. Veličino pripišite našemu Bogu.',
        4: 'On je Skala, njegovo delo je popolno, kajti vse njegove poti so sodba. Bog resnice in brez krivičnosti, pravičen in iskren je on.',
        5: 'Izpridili so se, njihov madež ni madež njegovih otrok. Sprevržen in sprijen rod so.',
        6: 'Ali tako poplačate Gospodu, oh nespametno in ne-modro ljudstvo? Mar ni on tvoj oče, ki te je kupil? Mar te ni on naredil in te postavil?',
        7: 'Spomnite se dni od davnine, preudarite leta mnogih rodov. Vprašajte svojega očeta in vam bo pokazal, svoje starešine in ti bodo povedali.',
        8: 'Ko je Najvišji narodom razdelil njihovo dediščino, ko je ločil Adamove sinove, je ljudstvu postavil meje, glede na število Izraelovih otrok.',
        9: 'Kajti Gospodov delež je njegovo ljudstvo; Jakob je žreb njegove dediščine.',
        10: 'Našel ga je v zapuščeni deželi in v opustošeni, tuleči divjini. Vodil ga je naokrog, poučeval ga je, ga varoval kakor punčico svojega očesa.',
        11: 'Kakor orlica spodbuja svoje gnezdo, frfota nad svojimi mladiči, široko razširja svoje peruti, jih jemlje in nosi na svojih perutih,',
        12: 'tako ga je Gospod sam vodil in tam z njim ni bilo tujega boga.',
        13: 'Dal mu je jahati na visokih krajih zemlje, da bi lahko jedel donos od polj in storil mu je, da sesa med iz skale in olje iz kremenčeve skale,',
        14: 'maslo goveda in mleko ovc, s tolščo jagnjet in ovni bašánske pasme in koze, z najbogatejšo notranjostjo zrna in pil si čisto kri grozdnih jagod.',
        15: 'Toda Ješurún se je odebelil in brcal. Postal si debel, postal si gost, pokrit si z maščobo. Potem je zapustil Boga, ki ga je naredil in preziral Skalo rešitve svoje duše.',
        16: 'S tujimi bogovi so ga dražili do ljubosumnosti, z ogabnostmi so ga izzivali k jezi.',
        17: 'Žrtvovali so hudičem, ne pa Bogu, bogovom, ki jih niso poznali, novim bogovom, ki so se na novo pojavili, ki se jih vaši očetje niso bali.',
        18: 'Nisi mislil na Skalo, ki te je spočela in pozabil si Boga, ki te je oblikoval.',
        19: 'Ko je Gospod to videl, jih je zaničeval, ker so ga njegovi sinovi in njegove hčere jezili.',
        20: 'Rekel je: ›Svoj obraz bom skril pred njimi. Videl bom kakšen bo njihov konec, kajti zelo kljubovalen rod so, otroci, v katerih ni vere.',
        21: 'Ganili so me do ljubosumja s tem, kar ni Bog; s svojimi ničevostmi so me izzivali k jezi. Do ljubosumja jih bom ganil s tistimi, ki niso ljudstvo; k jezi jih bom izzival z nespametnim narodom.',
        22: 'Kajti v moji jezi je vžgan ogenj in gorel bo do najnižjega pekla in použil bo zemljo z njenim narastom in vžgal bo temelje gora.',
        23: 'Nanje bom nakopičil vragolije, nanje bom poslal svoje puščice.',
        24: 'Izčrpani bodo z lakoto in požrti z gorečo vročino in z grenkim uničenjem. Nadnje bom poslal tudi zobe zveri, s strupom kač, [ki se plazijo po] prahu.',
        25: 'Meč zunaj in strahota znotraj bo uničila tako mladeniča kot devico, tudi dojenčka z možem sivih las.‹',
        26: 'Rekel sem: ›Razkropil jih bom v kote in storil bom, da spomin nanje zbledi med ljudmi.',
        27: 'Mar ni bilo, da sem se bal sovražnikovega besa, da se ne bi njihovi nasprotniki čudno obnašali in da ne bi rekli: ›Naša roka je visoko in Gospod ni storil vsega tega.‹‹',
        28: 'Kajti oni so narod brez preudarnosti niti ni nobenega razumevanja v njih.',
        29: 'Oh, da bi bili modri, da bi to razumeli, da bi preudarili svoj zadnji konec!',
        30: 'Kako naj jih eden prežene tisoč in dva pripravita deset tisoč, da bežijo, razen, da jih je njihova Skala prodala in jih je Gospod izročil?',
        31: 'Kajti njihova skala ni kakor naša Skala, celo sami naši sovražniki so sodniki.',
        32: 'Kajti njihova trta je iz sódomske trte in iz gomórskih polj. Njihovo grozdje je grozdje žolča, njihovi grozdi so grenki.',
        33: 'Njihovo vino je strup zmajev in krut strup kober.',
        34: 'Mar ni to prihranjeno v shrambi z menoj in zapečateno med mojimi zakladi?',
        35: 'Meni pripada maščevanje in povračilo. Njihovo stopalo bo zdrsnilo ob pravem času, kajti dan njihove katastrofe je pri roki in stvari, ki bodo prišle nadnje, hitijo.',
        36: 'Kajti Gospod bo sodil svoje ljudstvo in se pokesal zaradi svojih služabnikov, ko vidi, da je njihova moč odšla in tam ni nikogar zaprtega ali preostalega.',
        37: 'Rekel bo: ›Kje so njihovi bogovi, njihova skala, v katero so zaupali,',
        38: 'ki so jedli tolščo svojih klavnih daritev in pili vino svojih pitnih daritev? Naj vstanejo in vam pomagajo in bodo vaša zaščita.',
        39: 'Poglej sedaj, da sem jaz, celó jaz sam in tukaj ni boga z menoj. Jaz ubijam in jaz oživljam; jaz ranim in jaz ozdravljam. Niti tam ni nobenega, ki lahko osvobodi iz moje roke.',
        40: 'Kajti svojo roko dvignem do neba in rečem: ›Jaz živim na veke.‹',
        41: 'Če nabrusim svoj lesketajoči meč in moja roka zgrabi sodbo, bom povrnil maščevanje svojim sovražnikom in nagradil tiste, ki me sovražijo.',
        42: 'Svoje puščice bom opijanil s krvjo in moj meč bo žrl meso in to s krvjo umorjenih in ujetnikov, od začetka maščevanj nad sovražnikom.‹',
        43: 'Veselite se, oh vi narodi, z njegovim ljudstvom, kajti maščeval bo kri svojih služabnikov in povrnil bo maščevanje svojim nasprotnikom in usmiljen bo do svoje dežele in do svojega ljudstva.«',
        44: 'Mojzes je prišel in vse besede te pesmi spregovoril v ušesa ljudstva, on in Nunov sin Hošéa.',
        45: 'Mojzes je končal govorjenje vseh teh besed vsemu Izraelu.',
        46: 'Rekel jim je: »Nastavite svoja srca k vsem besedam, ki jih ta dan pričujem med vami, ki jih boste zapovedali svojim otrokom, da jih obeležujejo, da jih storijo, vse besede te postave.',
        47: 'Kajti to za vas ni prazna stvar, ker to je vaše življenje in zaradi te stvari boste podaljšali svoje dni v deželi, kamor greste čez Jordan, da jo vzamete v last.«',
        48: 'Gospod je ta isti dan spregovoril Mojzesu, rekoč:',
        49: '»Povzpni se na to gorovje Abarím, na goro Nebó, ki je v deželi Moáb, ki je nasproti Jerihe in poglej kánaansko deželo, ki jo dajem Izraelovim otrokom v posest.',
        50: 'Umri na gori, kamor se povzpneš in bodi zbran k svojemu ljudstvu, kakor je tvoj brat Aron umrl na gori Hor in je bil zbran k svojemu ljudstvu,',
        51: 'ker sta grešila zoper mene med Izraelovimi otroki pri vodah Meríba [v] Kadešu, v Cinski divjini, ker me nista izkazala svetega v sredi Izraelovih otrok.',
        52: 'Vendar boš deželo videl pred seboj, toda ne boš šel tja, v deželo, ki sem jo dal Izraelovim otrokom.«',
    },
    33: {
        1: 'To je blagoslov, s katerim je Mojzes, Božji mož, pred svojo smrtjo blagoslovil Izraelove otroke.',
        2: 'Rekel je: » Gospod je prišel s Sinaja in se iz Seírja dvignil k njim. On sije z gore Parán in prišel je z deset tisoči svetih. Iz njegove desnice je šla zanje ognjena postava.',
        3: 'Da, ljubil je ljudstvo. Vsi njegovi sveti so v tvoji roki in usedli so se pri tvojih stopalih; vsak bo prejel od tvojih besed.',
        4: 'Mojzes nam je zapovedal postavo, torej dediščino Jakobove skupnosti.',
        5: 'In on je bil kralj v Ješurúnu, ko so se zbrali skupaj poglavarji ljudstva in so bili Izraelovi rodovi zbrani skupaj.',
        6: 'Naj Ruben živi in ne umre in naj njegovih mož ne bo malo.«',
        7: 'To je blagoslov za Juda. Rekel je: »Prisluhni, Gospod, Judovemu glasu in privedi ga k svojemu ljudstvu. Naj mu njegove roke zadoščajo in ti mu bodi pomoč pred njegovimi sovražniki.«',
        8: 'O Léviju je rekel: » Naj bosta tvoj Tumím in tvoj Urím s tvojim svetim, ki si ga preizkusil pri Masi in s katerim si se prepiral pri vodah Meríbe,',
        9: 'ki je svojemu očetu in svoji materi rekel: ›Nisem ga videl.‹ Niti ni priznal svojih bratov niti spoznal svojih lastnih otrok, kajti obeležili so tvojo besedo in se držali tvoje zaveze.',
        10: 'Jakoba bodo učili tvojih sodb in Izraela tvoje postave. Pred teboj bodo postavili kadilo in celotno žgalno daritev na tvoj oltar.',
        11: 'Blagoslovi Gospod njegovo imetje in sprejmi delo njegovih rok. Skozi ledja udari tiste, ki vstajajo zoper njega in izmed tistih, ki ga sovražijo, da ne vstanejo ponovno.«',
        12: 'In o Benjaminu je rekel: »Ljubljen od Gospoda bo varno prebival pri njem in Gospod ga bo ves dan pokrival in prebival bo med njegovimi rameni.«',
        13: 'O Jožefu je rekel: »Njegova dežela naj bo blagoslovljena od Gospoda, za dragocene stvari z neba in za roso in za globino, ki leži spodaj',
        14: 'in za dragoceno sadje, porojeno s soncem in za dragocene stvari, navržene z luno',
        15: 'in za vodilne stvari starodavnih gora in za dragocene stvari trajnih hribov',
        16: 'in za dragocene stvari zemlje in njene polnosti in za dobro voljo tistega, ki je prebival v grmu. Naj nad Jožefovo glavo pride blagoslov in na vrh glave tistega, ki je bil ločen od svojih bratov.',
        17: 'Njegova slava je podobna prvencu njegovega bikca in njegovi rogovi so podobni rogovom samorogov. Z njimi bo suval ljudstvo skupaj h koncem zemlje, in oni so Efrájimovi deset tisoči in oni so Manásejevi deset tisoči.«',
        18: 'O Zábulonu je rekel: »Veseli se Zábulon v svojem odhajanju in Isahár v svojih šotorih.',
        19: 'Ljudstvo bosta klicala h gori. Tam bodo darovali klavne daritve pravičnosti, kajti sesali bodo od obilja morij in od zakladov, skritih v pesku.«',
        20: 'O Gadu je rekel: »Blagoslovljen bodi, kdor povečuje Gad. Ta prebiva kakor lev in trga laket s têmenom.',
        21: 'Prvi del si je priskrbel zase, ker je bil tam, v deležu postavodajalca, dokončan; in prišel je s poglavarji ljudstva, izvršil je Gospodovo pravičnost in njegove sodbe z Izraelom.«',
        22: 'O Danu je rekel: »Dan je levji mladič. Poskakoval bo iz Bašána.«',
        23: 'O Neftáliju je rekel: »Oh Neftáli, nasičen z naklonjenostjo in poln Gospodovega blagoslova. Ti poseduj zahod in jug.«',
        24: 'O Aserju je rekel: »Aser naj bo blagoslovljen z otroki. Sprejemljiv naj bo svojim bratom in naj svoje stopalo omoči v olju.',
        25: 'Tvoji čevlji bodo železo in bron in kakor tvoji dnevi, takšna bo tvoja moč.',
        26: 'Nobenega ni podobnega Ješurúnovemu Bogu, ki jaha na nebesih v tvojo pomoč in v svoji odličnosti na nebu.',
        27: 'Večen Bog je tvoje zatočišče in spodaj so večne roke in on bo izpred tebe sunil sovražnika in rekel bo: ›Uniči jih.‹',
        28: 'Potem bo Izrael sam prebival na varnem. Jakobov studenec bo na deželi žita in vina; tudi njegovo nebo bo kapljalo roso.',
        29: 'Srečen si ti, oh Izrael. Kdo je tebi podoben, oh ljudstvo, rešeno po Gospodu, ščitu tvoje pomoči in kdo je meč tvoje odličnosti! In tvoji sovražniki ti bodo najdeni kot lažnivci, in teptal jih boš na njihovih visokih krajih.«',
    },
    34: {
        1: 'Mojzes se je iz moábskih ravnin dvignil na goro Nebó, k vrhu Pisge, ki je nasproti Jerihe. In Gospod mu je pokazal vso deželo Gileád, do Dana',
        2: 'in ves Neftáli, Efrájimovo in Manásejevo deželo in vso Judovo deželo, do skrajnega morja,',
        3: 'in jug in ravnino jerihonske doline, mesto palmovih dreves, do Coarja.',
        4: 'Gospod mu je rekel: »To je dežela, ki sem jo prisegel Abrahamu, Izaku in Jakobu, rekoč: ›Dal jo bom tvojemu semenu.‹ Dal sem ti, da jo vidiš s svojimi očmi, toda ne boš šel tja preko.«',
        5: 'Tako je Gospodov služabnik Mojzes umrl tam v moábski deželi, glede na Gospodovo besedo.',
        6: 'Pokopal ga je v dolini, v moábski deželi nasproti Bet Peórja, toda noben človek ne pozna njegovega mavzoleja do današnjega dne.',
        7: 'Mojzes je bil star sto dvajset let, ko je umrl. Njegovo oko ni bilo zatemnjeno niti se njegova naravna sila ni zmanjšala.',
        8: 'Izraelovi otroci so na moábskih ravninah trideset dni jokali za Mojzesom; tako so bili dnevi jokanja in žalovanja za Mojzesom končani.',
        9: 'Nunov sin Józue pa je bil poln duha modrosti, kajti Mojzes je nanj položil svoji roki in Izraelovi otroci so mu prisluhnili in storili, kakor je Gospod zapovedal Mojzesu.',
        10: 'In od takrat v Izraelu ni vstal prerok, podoben Mojzesu, ki ga je Gospod poznal iz obličja v obličje,',
        11: 'v vseh znamenjih in čudežih, ki mu jih je Gospod poslal, da jih v egiptovski deželi stori faraonu in vsem njegovim služabnikom in vsej njegovi deželi',
        12: 'in v vsej tisti mogočni roki in vsej veliki strahoti, ki jo je Mojzes pokazal pred očmi vsega Izraela.',
    },
}
